/* AFTER SIGNAL sortie voice V1 (2026-09-28).
   GENERATED by staging/sortie_voice_20260928/build_sortie_runtime.py from sortie_voice_runtime.template.js - edit the template.
   Sortie lines, separate from the lobby tap lines (user 2026-09-28: "출격 음성은 따로 만들어라. 출격에 어울리는 음성들로").
   Where they play:
   - 출격 편성 (lobby): adding a member to the formation - that member speaks, the caption sits above the card;
   - battle start (chapterCombat / extraCombat): when the common runtime marks body[data-af-combat-started="true"], the
     squad leader (the first member of body[data-af-dev-party] with lines) calls the sortie; caption at the top right.
     On a chapter-boss stage the boss comm is queued at the same moment; chapterCombat holds it while remainingMs() > 0,
     so the comm follows the sortie call instead of cutting it off (one host voice channel).
   5 lines per member rotate 1 -> 5 -> 1, shared by both places (localStorage aftersignal:sortie-voice:v1).
   Voices are keyed by language: Japanese (default) and Korean (2026-09-29; the game settings write localStorage
   aftersignal:voice-lang = "ko"). The caption is Korean (CAPTION_LANG) whatever the voice - each line keeps {ko, ja}
   text, the Japanese one for the later Japanese edition.
   Inside index.html the host plays the clip (one voice channel, BGM duck, stored VOICE mute); a standalone page plays it
   itself. The lobby tap voice (AFTERSIGNAL_LOBBY_TAP_VOICE_V1.js) and this script announce each line with the window
   event "aftersignal:char-voice", so whichever speaks last owns the channel and the other hides its caption. */
(()=>{
  "use strict";
  const LINES={"ja":{"mira":[{"src":"../assets/voice/sortie/ja/mira_1.mp3","ms":6100,"text":{"ko":"미라 보스, 출격합니다. 링크 접속, 전 대원 응답 확인.","ja":"ミラ・ヴォス、出撃します。リンク接続、全隊員の応答を確認。"}},{"src":"../assets/voice/sortie/ja/mira_2.mp3","ms":5140,"text":{"ko":"후열, 배치에 들어갑니다. 전선의 사선은 제가 보정하겠습니다.","ja":"後列、配置につきます。前線の射線は、私が補正します。"}},{"src":"../assets/voice/sortie/ja/mira_3.mp3","ms":4460,"text":{"ko":"R-0 카빈, 안전장치 해제. 교전을 개시합니다.","ja":"R-0カービン、安全装置解除。交戦を開始します。"}},{"src":"../assets/voice/sortie/ja/mira_4.mp3","ms":6730,"text":{"ko":"작전 범위, 확인했습니다. 전원 귀환을 조건에 추가하겠습니다.","ja":"作戦範囲、確認しました。全員で戻ることを、条件に加えます。"}},{"src":"../assets/voice/sortie/ja/mira_5.mp3","ms":6130,"text":{"ko":"화이트 릴레이, 전개합니다. 지평선 너머까지 신호를 보내겠습니다.","ja":"ホワイト・リレー、展開します。地平線の向こうまで、信号を届けます。"}}],"haneul":[{"src":"../assets/voice/sortie/ja/haneul_1.mp3","ms":4240,"text":{"ko":"하늘-7, 출격. 정비 드론, 전 기체 동행.","ja":"ハヌル-7、出撃。整備ドローン、全機随伴。"}},{"src":"../assets/voice/sortie/ja/haneul_2.mp3","ms":4450,"text":{"ko":"오염률, 측정 개시. 보호 채널, 열어 둘게.","ja":"汚染率、測定開始。保護チャンネル、開いておく。"}},{"src":"../assets/voice/sortie/ja/haneul_3.mp3","ms":4300,"text":{"ko":"중열, 정위치. 적 분리도, 판정 중.","ja":"中列、定位置。敵の分離度、判定中。"}},{"src":"../assets/voice/sortie/ja/haneul_4.mp3","ms":5600,"text":{"ko":"생존 확률, 상승 중. ……정정. 내가 올릴 거야.","ja":"生存確率、上昇中。……訂正。わたしが、上げる。"}},{"src":"../assets/voice/sortie/ja/haneul_5.mp3","ms":5070,"text":{"ko":"사령관, 귀환 지점 등록했어. ……같이 돌아가.","ja":"司令官、帰還地点を登録した。……一緒に、戻る。"}}],"sera":[{"src":"../assets/voice/sortie/ja/sera_1.mp3","ms":5820,"text":{"ko":"세라 플린트, 먼저 나간다. 너희는 내 발자국 밟고 따라와.","ja":"セラ・フリント、先に出るよ。あんたらは、あたしの足跡を踏んで来な。"}},{"src":"../assets/voice/sortie/ja/sera_2.mp3","ms":5250,"text":{"ko":"디지털이 입을 다물어도 분필 선은 안 지워져. 자, 간다.","ja":"デジタルが黙っても、チョーク線は消えない。さあ、行くぞ。"}},{"src":"../assets/voice/sortie/ja/sera_3.mp3","ms":5080,"text":{"ko":"조명탄, 점화 준비 끝. 어두운 데는 전부 내가 비춰 줄게.","ja":"フレア、点火準備よし。暗いところは、全部あたしが照らしてやる。"}},{"src":"../assets/voice/sortie/ja/sera_4.mp3","ms":4660,"text":{"ko":"전열은 나야. 종이 지도는 가슴 주머니에 넣어 뒀어.","ja":"前衛はあたしだ。紙の地図は、胸ポケットに入れてある。"}},{"src":"../assets/voice/sortie/ja/sera_5.mp3","ms":3700,"text":{"ko":"살아서 돌아올 때까지가 작전이잖아. 늦지 마.","ja":"生きて帰るまでが作戦だろ、遅れんなよ。"}}],"astra":[{"src":"../assets/voice/sortie/ja/astra_1.mp3","ms":5140,"text":{"ko":"아스트라 벨, 출격한다. 시야 양호, 오차 없음.","ja":"アストラ・ベル、出撃する。視界良好、誤差なし。"}},{"src":"../assets/voice/sortie/ja/astra_2.mp3","ms":3690,"text":{"ko":"탄도, 계산 완료. 첫 발부터 맞힌다.","ja":"弾道、計算済み。一発目から当てる。"}},{"src":"../assets/voice/sortie/ja/astra_3.mp3","ms":4480,"text":{"ko":"중열에서 전역을 관측한다. 사각은 내가 메운다.","ja":"中列から全域を観測する。死角は、私が埋める。"}},{"src":"../assets/voice/sortie/ja/astra_4.mp3","ms":7020,"text":{"ko":"불명 적영, 하나. 확인할 때까지 쏘지 않는다. 확인하면 빗나가지 않는다.","ja":"不明な敵影、一。確認するまで撃たない。確認したら、外さない。"}},{"src":"../assets/voice/sortie/ja/astra_5.mp3","ms":5480,"text":{"ko":"잔광 각도, 고정. 사령관, 쏠 곳을 지시해라.","ja":"残光の角度、固定。司令官、撃つ場所を示せ。"}}],"tessa":[{"src":"../assets/voice/sortie/ja/tessa_1.mp3","ms":5460,"text":{"ko":"테사 룬, 앞으로 나간다. 전열은 내가 받친다.","ja":"テッサ・ルーン、前へ出る。戦列は私が支える。"}},{"src":"../assets/voice/sortie/ja/tessa_2.mp3","ms":4310,"text":{"ko":"방벽 전개. 이 선부터는 아무도 못 지나간다.","ja":"防壁、展開。この線から先には、誰も通さない。"}},{"src":"../assets/voice/sortie/ja/tessa_3.mp3","ms":4410,"text":{"ko":"교대 순서는 정해 뒀다. 쓰러지기 전에 물린다.","ja":"交代の順番は決めてある。倒れる前に、下がらせる。"}},{"src":"../assets/voice/sortie/ja/tessa_4.mp3","ms":4640,"text":{"ko":"파운드리 헤비, 장전 완료. 엄호 사격 개시한다.","ja":"ファウンドリ・ヘビー、装填完了。援護射撃、開始する。"}},{"src":"../assets/voice/sortie/ja/tessa_5.mp3","ms":3870,"text":{"ko":"전원 돌아간다. 그게 오늘의 약속이다.","ja":"全員で帰る。それが、今日の約束だ。"}}],"naru":[{"src":"../assets/voice/sortie/ja/naru_1.mp3","ms":6140,"text":{"ko":"나루 세이건, 출격합니다. 다치면 바로 불러 주세요.","ja":"ナル・セーガン、出撃します。怪我をしたら、すぐに呼んでくださいね。"}},{"src":"../assets/voice/sortie/ja/naru_2.mp3","ms":6010,"text":{"ko":"후열에서 모두의 맥을 보고 있어요. 무리만은 하지 마세요.","ja":"後列から、全員の脈を見ています。無理だけは、しないで。"}},{"src":"../assets/voice/sortie/ja/naru_3.mp3","ms":5760,"text":{"ko":"생존의 연속성, 확보하겠습니다. 한 명도 끊기게 두지 않아요.","ja":"生存の連続性、確保します。一人も、途切れさせません。"}},{"src":"../assets/voice/sortie/ja/naru_4.mp3","ms":5750,"text":{"ko":"붕대도 지혈대도 다 챙겼어요. 안심하고 앞으로 나가세요.","ja":"包帯も止血帯も、揃っています。安心して、前に出てください。"}},{"src":"../assets/voice/sortie/ja/naru_5.mp3","ms":6700,"text":{"ko":"쓰러진 사람은 반드시 데리고 돌아옵니다. 그게 제 싸움 방식이에요.","ja":"倒れた人は、必ず連れて帰ります。それが、私の戦い方です。"}}],"karin":[{"src":"../assets/voice/sortie/ja/karin_1.mp3","ms":3160,"text":{"ko":"알겠습니다. 카린 베가, 출격합니다.","ja":"了解。カリン・ヴェガ、出撃します。"}},{"src":"../assets/voice/sortie/ja/karin_2.mp3","ms":5030,"text":{"ko":"후방 방벽, 전개합니다. 퇴로는 제가 확보하겠습니다.","ja":"後方防壁、展開します。退路は、私が確保します。"}},{"src":"../assets/voice/sortie/ja/karin_3.mp3","ms":4980,"text":{"ko":"파운드리 중탄, 장전. 엄호 사격, 언제든 가능합니다.","ja":"ファウンドリ重弾、装填。援護射撃、いつでもいけます。"}},{"src":"../assets/voice/sortie/ja/karin_4.mp3","ms":4570,"text":{"ko":"맹세는 벽입니다. 오늘도 뒤에 선 사람들을 지키겠습니다.","ja":"誓いは壁です。今日も、後ろに立つ人を守ります。"}},{"src":"../assets/voice/sortie/ja/karin_5.mp3","ms":4620,"text":{"ko":"회수할 때까지 누구 하나 두고 가지 않겠습니다. 명령을 내려 주십시오.","ja":"回収まで、誰ひとり置いていきません。命令を、どうぞ。"}}],"serin":[{"src":"../assets/voice/sortie/ja/serin_1.mp3","ms":3540,"text":{"ko":"세린, 나간다. 좌표 확정.","ja":"セリン、出る。座標、確定。"}},{"src":"../assets/voice/sortie/ja/serin_2.mp3","ms":4590,"text":{"ko":"후열에서 사선을 교차시킨다. 1도의 오차도 허용하지 않는다.","ja":"後列から射線を交差させる。一度のずれも、許さない。"}},{"src":"../assets/voice/sortie/ja/serin_3.mp3","ms":4080,"text":{"ko":"외곽 봉쇄선 전개. 도주로는 남기지 않는다.","ja":"外周の封鎖線、展開。逃げ道は、残さない。"}},{"src":"../assets/voice/sortie/ja/serin_4.mp3","ms":5570,"text":{"ko":"지키기로 한 상대는 지킨다. 이유는 그걸로 충분하다.","ja":"守ると決めた相手は守る。理由は、それで十分だ。"}},{"src":"../assets/voice/sortie/ja/serin_5.mp3","ms":4680,"text":{"ko":"삼각 봉인, 준비 완료. 사령관, 사격 허가를.","ja":"三角封印、準備完了。司令官、射撃許可を。"}}],"luna":[{"src":"../assets/voice/sortie/ja/luna_1.mp3","ms":6220,"text":{"ko":"루나, 출격합니다. 문턱을 넘기 전에 한 호흡.","ja":"ルナ、出撃します。敷居を越える前に、一呼吸。"}},{"src":"../assets/voice/sortie/ja/luna_2.mp3","ms":6400,"text":{"ko":"전열의 벽은 제가 맡겠습니다. 뒤에 계신 분들은 호흡을 고르세요.","ja":"前列の壁は、私が務めます。後ろの方は、呼吸を整えてください。"}},{"src":"../assets/voice/sortie/ja/luna_3.mp3","ms":5460,"text":{"ko":"돌아올 길은 이미 확인해 두었습니다. 안심하고 나아가죠.","ja":"戻り道は、もう確かめてあります。安心して進みましょう。"}},{"src":"../assets/voice/sortie/ja/luna_4.mp3","ms":5050,"text":{"ko":"파운드리 월, 전개. 여기를 돌아올 곳으로 만들겠습니다.","ja":"ファウンドリ・ウォール、展開。ここを、帰る場所にします。"}},{"src":"../assets/voice/sortie/ja/luna_5.mp3","ms":6030,"text":{"ko":"의식은 모두가 돌아와야 끝납니다. 자, 시작하죠.","ja":"儀式は、全員が戻って終わりです。さあ、始めましょう。"}}],"arin":[{"src":"../assets/voice/sortie/ja/arin_1.mp3","ms":5580,"text":{"ko":"아린, 출격합니다. 주석 카드는 전부 챙겼습니다.","ja":"アリン、出撃します。注釈カードは、全部持ちました。"}},{"src":"../assets/voice/sortie/ja/arin_2.mp3","ms":6480,"text":{"ko":"작전이라는 가설을 이제 검증하겠습니다. 반례는 현장에서 찾죠.","ja":"作戦という仮説を、これから検証します。反例は、現場で探しましょう。"}},{"src":"../assets/voice/sortie/ja/arin_3.mp3","ms":5670,"text":{"ko":"드론 제어식, 기동. 변수는 전부 공개하겠습니다.","ja":"ドローン制御式、起動。変数は、すべて公開します。"}},{"src":"../assets/voice/sortie/ja/arin_4.mp3","ms":5300,"text":{"ko":"적 분류는 아직 가설입니다. 확인하면서 나아갈게요.","ja":"敵の分類は、まだ仮説です。確かめながら進みますね。"}},{"src":"../assets/voice/sortie/ja/arin_5.mp3","ms":5680,"text":{"ko":"사령관님의 판단식, 확실히 받았습니다. 제가 증명해 보이겠습니다.","ja":"司令官の判断式、確かに受け取りました。私が、証明してみせます。"}}],"jaein":[{"src":"../assets/voice/sortie/ja/jaein_1.mp3","ms":4040,"text":{"ko":"재인 복스, 출격! 라이브 시간이야!","ja":"ジェイン・ヴォックス、出撃！　ライブの時間だよ！"}},{"src":"../assets/voice/sortie/ja/jaein_2.mp3","ms":4500,"text":{"ko":"드론들, 코러스 배치! 적의 리듬, 전부 무너뜨리자.","ja":"ドローンたち、コーラス配置！　敵のリズム、全部崩しちゃおう。"}},{"src":"../assets/voice/sortie/ja/jaein_3.mp3","ms":5390,"text":{"ko":"후열에서 비트를 새길게. 너희는 그 템포로 달려.","ja":"後列からビートを刻むよ。きみたちは、そのテンポで走って。"}},{"src":"../assets/voice/sortie/ja/jaein_4.mp3","ms":5290,"text":{"ko":"내 목소리가 닿는 한, 이 전장은 내 무대니까.","ja":"わたしの声が届く限り、この戦場は、わたしのステージだから。"}},{"src":"../assets/voice/sortie/ja/jaein_5.mp3","ms":5460,"text":{"ko":"카운트 간다, 원, 투, 쓰리! 출격!","ja":"カウント行くよ、ワン、ツー、スリー！　出撃！"}}],"roa":[{"src":"../assets/voice/sortie/ja/roa_1.mp3","ms":4190,"text":{"ko":"로아, 출격할게! 코일 예열은 완벽해.","ja":"ロア、出撃するよ！　コイルの予熱は、ばっちり。"}},{"src":"../assets/voice/sortie/ja/roa_2.mp3","ms":5900,"text":{"ko":"포지 오버드라이브, 풀가동! 오늘 이 녀석, 기분 좋네.","ja":"フォージ・オーバードライブ、全開！　今日のこいつは、機嫌がいいね。"}},{"src":"../assets/voice/sortie/ja/roa_3.mp3","ms":6540,"text":{"ko":"망가지면 그 자리에서 용접할게. 그러니까 앞만 봐도 돼.","ja":"壊れたら、その場で溶接する。だから、前だけ見てていいよ。"}},{"src":"../assets/voice/sortie/ja/roa_4.mp3","ms":5940,"text":{"ko":"과열 볼트, 장전 완료! 볼트 하나까지 전부 써 버릴 거야.","ja":"過熱ボルト、装填完了！　ボルト一本まで、全部使い切ってやる。"}},{"src":"../assets/voice/sortie/ja/roa_5.mp3","ms":5790,"text":{"ko":"돌아오면 다들 장비 점검할 거야. 부숴도 되니까, 살아서만 돌아와.","ja":"帰ったら、みんなの装備を点検するからね。壊してもいいけど、生きて帰ってよ。"}}],"noella":[{"src":"../assets/voice/sortie/ja/noella_1.mp3","ms":5760,"text":{"ko":"노엘라 크로스, 출격하겠습니다. 모두의 무사를 기도하고 있습니다.","ja":"ノエラ・クロス、出撃いたします。皆さんの無事を、祈っています。"}},{"src":"../assets/voice/sortie/ja/noella_2.mp3","ms":4040,"text":{"ko":"오늘의 싸움도 제가 증인으로 끝까지 지켜보겠습니다.","ja":"今日の戦いも、私が証人として見届けます。"}},{"src":"../assets/voice/sortie/ja/noella_3.mp3","ms":7130,"text":{"ko":"십자 봉인탄, 장전했습니다. 용서와는 별개로, 쏠 것은 쏩니다.","ja":"十字の封印弾、装填しました。赦しとは別に、撃つべきものは撃ちます。"}},{"src":"../assets/voice/sortie/ja/noella_4.mp3","ms":6610,"text":{"ko":"후열에서 여러분의 등을 지켜보고 있어요. 돌아보지 않으셔도 괜찮습니다.","ja":"後列から、皆さんの背中を見ています。振り返らなくても、大丈夫です。"}},{"src":"../assets/voice/sortie/ja/noella_5.mp3","ms":6440,"text":{"ko":"남겨진 이들의 증언을 여기서 끝나게 두지 않겠습니다. 자, 가시죠.","ja":"残された人の証言を、ここで終わらせはしません。さあ、参りましょう。"}}],"ria":[{"src":"../assets/voice/sortie/ja/ria_1.mp3","ms":4760,"text":{"ko":"리아, 선봉에 선다! 돌파구는 내가 연다.","ja":"リア、先陣を切る！　突破口は、あたしが開ける。"}},{"src":"../assets/voice/sortie/ja/ria_2.mp3","ms":5550,"text":{"ko":"곧장 가서 곧장 뚫는다. 뒤는 따라와.","ja":"まっすぐ行って、まっすぐ抜く。後ろは、ついて来い。"}},{"src":"../assets/voice/sortie/ja/ria_3.mp3","ms":5100,"text":{"ko":"펄스 랜스, 충전 완료! 정면의 문을 억지로 열어 주지.","ja":"パルスランス、充填完了！　正面の扉を、こじ開けてやる。"}},{"src":"../assets/voice/sortie/ja/ria_4.mp3","ms":4790,"text":{"ko":"등은 맡겼어. 그러니까 난 뒤돌아보지 않아.","ja":"背中は預けた。だから、あたしは振り返らない。"}},{"src":"../assets/voice/sortie/ja/ria_5.mp3","ms":3390,"text":{"ko":"중앙을 연다. 사령관, 신호를 줘.","ja":"中央を開ける。司令官、合図をくれ。"}}],"bomin":[{"src":"../assets/voice/sortie/ja/bomin_1.mp3","ms":4050,"text":{"ko":"보민, 출격합니다. 잔탄 확인했습니다.","ja":"ボミン、出撃します。残弾、確認しました。"}},{"src":"../assets/voice/sortie/ja/bomin_2.mp3","ms":5750,"text":{"ko":"쏘기 전에 세 번 확인하겠습니다. ……그래도 늦지는 않겠습니다.","ja":"撃つ前に、三回確かめます。……でも、遅れはしません。"}},{"src":"../assets/voice/sortie/ja/bomin_3.mp3","ms":5210,"text":{"ko":"사격선, 유지하겠습니다. 아군 앞에는 한 발도 떨어뜨리지 않겠습니다.","ja":"射撃線、維持します。味方の前には、一発も落としません。"}},{"src":"../assets/voice/sortie/ja/bomin_4.mp3","ms":4690,"text":{"ko":"레일 충전 완료. 사각 확인, 끝났습니다.","ja":"レール、充電完了。死角の確認、終わりました。"}},{"src":"../assets/voice/sortie/ja/bomin_5.mp3","ms":3160,"text":{"ko":"오늘도 오발 제로로 돌아오겠습니다. 약속입니다.","ja":"今日も誤射ゼロで帰ります、約束です。"}}],"orin":[{"src":"../assets/voice/sortie/ja/orin_1.mp3","ms":4100,"text":{"ko":"오린 베일, 출격한다. 심리를 개시한다.","ja":"オリン・ヴェイル、出撃する。審理を開始する。"}},{"src":"../assets/voice/sortie/ja/orin_2.mp3","ms":5080,"text":{"ko":"증거를 모아라. 판결은 그 뒤에 내린다.","ja":"証拠を集めよ。判決は、その後で下す。"}},{"src":"../assets/voice/sortie/ja/orin_3.mp3","ms":4900,"text":{"ko":"어드주디케이터, 장전. 집행 준비는 끝났다.","ja":"アジュディケーター、装填。執行の準備は整った。"}},{"src":"../assets/voice/sortie/ja/orin_4.mp3","ms":4460,"text":{"ko":"적의 이의는 받아들이지 않는다. 효력을 정지한다.","ja":"敵の異議は、認めない。効力を停止する。"}},{"src":"../assets/voice/sortie/ja/orin_5.mp3","ms":4440,"text":{"ko":"사령관, 그대의 명령을 이 작전의 판결로 삼는다.","ja":"司令官、君の命令を、この作戦の判決とする。"}}],"yunseo":[{"src":"../assets/voice/sortie/ja/yunseo_1.mp3","ms":5870,"text":{"ko":"기록. 출격 개시. 목적, 적성 신호 제거.","ja":"記録。出撃を開始。目的、敵性信号の排除。"}},{"src":"../assets/voice/sortie/ja/yunseo_2.mp3","ms":5730,"text":{"ko":"항목 추가. 대원 수, 확인 완료. 귀환 때도 같은 수를 기록함.","ja":"項目追加。隊員数、確認済み。帰還時も、同じ数を記録する。"}},{"src":"../assets/voice/sortie/ja/yunseo_3.mp3","ms":5820,"text":{"ko":"근거 없는 판정은 하지 않음. 교전하면서 검증함.","ja":"根拠のない判定は、しない。交戦しながら、検証する。"}},{"src":"../assets/voice/sortie/ja/yunseo_4.mp3","ms":5090,"text":{"ko":"판정 표식, 준비 완료. 빈칸은 전장에서 메움.","ja":"判定マーク、準備完了。空白は、戦場で埋める。"}},{"src":"../assets/voice/sortie/ja/yunseo_5.mp3","ms":5080,"text":{"ko":"주석. 이번 기록에는 손실 0이라고 적을 예정.","ja":"注釈。今回の記録には、損失ゼロと書く予定。"}}],"yura":[{"src":"../assets/voice/sortie/ja/yura_1.mp3","ms":4600,"text":{"ko":"유라, 출격할게. 경로는 이미 그려 뒀어.","ja":"ユラ、出撃するよ。ルートは、もう描いてある。"}},{"src":"../assets/voice/sortie/ja/yura_2.mp3","ms":4830,"text":{"ko":"내 뒤로 걸어. 발자국 위라면 안전하니까.","ja":"あたしの後ろを歩いて。足跡の上なら、安全だから。"}},{"src":"../assets/voice/sortie/ja/yura_3.mp3","ms":5660,"text":{"ko":"시야의 빈칸, 세 곳. 우회로로 전부 피해 갈게.","ja":"視界の空白、三か所。迂回路で、全部かわすよ。"}},{"src":"../assets/voice/sortie/ja/yura_4.mp3","ms":4830,"text":{"ko":"길 잃으면 나 불러. 지도는 지금부터 다시 그릴게.","ja":"道に迷ったら、あたしを呼んで。地図は、今から描き直す。"}},{"src":"../assets/voice/sortie/ja/yura_5.mp3","ms":4860,"text":{"ko":"돌아올 길까지 제대로 재 뒀어. 다 같이 돌아가자.","ja":"帰り道まで、ちゃんと測ってある。全員で戻ろう。"}}],"yeonhwa":[{"src":"../assets/voice/sortie/ja/yeonhwa_1.mp3","ms":5180,"text":{"ko":"연화, 출격합니다. 전 채널, 접속 확인했어요.","ja":"ヨンファ、出撃します。全チャンネル、接続を確認しました。"}},{"src":"../assets/voice/sortie/ja/yeonhwa_2.mp3","ms":5390,"text":{"ko":"퇴로 확보는 맡겨 주세요. 귀환선은 제가 지킬게요.","ja":"退路の確保は、任せてください。帰還線は、私が守ります。"}},{"src":"../assets/voice/sortie/ja/yeonhwa_3.mp3","ms":4870,"text":{"ko":"전열에 서겠습니다. 여러분의 목소리, 하나도 놓치지 않을게요.","ja":"前列に立ちます。皆さんの声、ひとつも聞き逃しません。"}},{"src":"../assets/voice/sortie/ja/yeonhwa_4.mp3","ms":5470,"text":{"ko":"앵커 플레이트, 고정. 통신을 분리해서 전장을 정리하겠습니다.","ja":"アンカープレート、固定。通信を分離して、戦場を整理します。"}},{"src":"../assets/voice/sortie/ja/yeonhwa_5.mp3","ms":5420,"text":{"ko":"사령관님의 목소리가 모두에게 닿도록. 중계, 시작하겠습니다.","ja":"司令官の声が、全員に届くように。中継、始めます。"}}],"narae":[{"src":"../assets/voice/sortie/ja/narae_1.mp3","ms":4400,"text":{"ko":"나래, 출격. 사선은 내가 가져간다.","ja":"ナレ、出撃。射線は、あたしがもらう。"}},{"src":"../assets/voice/sortie/ja/narae_2.mp3","ms":5180,"text":{"ko":"탄창, 가득. 먼저 쏘고 먼저 끝낸다.","ja":"マガジン、満タン。先に撃って、先に終わらせる。"}},{"src":"../assets/voice/sortie/ja/narae_3.mp3","ms":5170,"text":{"ko":"제압 연사, 간다! 고개 드는 놈부터 떨군다.","ja":"制圧連射、行くぞ！　頭を上げたやつから、落とす。"}},{"src":"../assets/voice/sortie/ja/narae_4.mp3","ms":5990,"text":{"ko":"연결부는 내가 사수한다. 그러니까 아무도 잃게 두지 않아.","ja":"連結部は、あたしが死守する。だから、誰も失わせない。"}},{"src":"../assets/voice/sortie/ja/narae_5.mp3","ms":4840,"text":{"ko":"속도라면 누구한테도 안 져. 늦지 마, 너희.","ja":"速さなら、誰にも負けない。遅れんなよ、あんたら。"}}],"moa":[{"src":"../assets/voice/sortie/ja/moa_1.mp3","ms":3190,"text":{"ko":"모아, 나간다! 앞은 내가 막는다.","ja":"モア、出るぞ！　前はあたしが止める。"}},{"src":"../assets/voice/sortie/ja/moa_2.mp3","ms":5320,"text":{"ko":"앵커 플레이트, 고정! 이 전열은 한 발짝도 안 물러난다.","ja":"アンカープレート、固定！　この戦列は、一歩も下げない。"}},{"src":"../assets/voice/sortie/ja/moa_3.mp3","ms":5520,"text":{"ko":"하, 탄띠는 넉넉해. 사양 않고 쏴 댈 거야.","ja":"はっ、弾帯はたっぷりある。遠慮なく撃ちまくるぞ。"}},{"src":"../assets/voice/sortie/ja/moa_4.mp3","ms":4200,"text":{"ko":"사선을 막는다. 너희는 내 뒤에서 쏴.","ja":"射線を塞ぐ。あんたらは、あたしの後ろから撃て。"}},{"src":"../assets/voice/sortie/ja/moa_5.mp3","ms":6070,"text":{"ko":"이중 봉쇄선 친다. 여기서부터는 내 방벽이야.","ja":"二重の封鎖線、張るぞ。ここから先は、あたしの防壁だ。"}}],"somi":[{"src":"../assets/voice/sortie/ja/somi_1.mp3","ms":5820,"text":{"ko":"소미, 출격합니다! ……기, 긴장되지만 괜찮아요!","ja":"ソミ、出撃します！　……き、緊張してますけど、大丈夫です！"}},{"src":"../assets/voice/sortie/ja/somi_2.mp3","ms":5270,"text":{"ko":"로터리, 회전 개시! 전열, 제가 받치겠습니다!","ja":"ロータリー、回転開始！　前列、わたしが支えます！"}},{"src":"../assets/voice/sortie/ja/somi_3.mp3","ms":5880,"text":{"ko":"중계, 접속했습니다. 여러분의 목소리, 제대로 이어 드릴게요.","ja":"中継、接続しました。皆さんの声、ちゃんと繋ぎます。"}},{"src":"../assets/voice/sortie/ja/somi_4.mp3","ms":5530,"text":{"ko":"무서워도 끊지 않을게요. 끝까지 계속 답하겠습니다!","ja":"怖くても、切りません。最後まで、答え続けます！"}},{"src":"../assets/voice/sortie/ja/somi_5.mp3","ms":3690,"text":{"ko":"보고합니다! 소미, 전투 배치 완료했습니다!","ja":"報告します！　ソミ、戦闘配置につきました！"}}],"bella":[{"src":"../assets/voice/sortie/ja/bella_1.mp3","ms":4990,"text":{"ko":"벨라, 나간다. 다친 사람은 나한테 데려와.","ja":"ベラ、出るよ。怪我人は、あたしのところに運びな。"}},{"src":"../assets/voice/sortie/ja/bella_2.mp3","ms":4760,"text":{"ko":"이송 순서는 내가 정해. 불평은 살아서 돌아온 다음에 들을게.","ja":"搬送の順番は、あたしが決める。文句は、生きて帰ってから聞く。"}},{"src":"../assets/voice/sortie/ja/bella_3.mp3","ms":4660,"text":{"ko":"루멘 방호, 전개. 피 나면 바로 말해.","ja":"ルーメン防護、展開。出血したら、すぐ言いな。"}},{"src":"../assets/voice/sortie/ja/bella_4.mp3","ms":6010,"text":{"ko":"자, 전원 건강. ……지금까지는. 그 상태로 돌아와.","ja":"はい、全員健康。……今のところはね。その状態で戻っておいで。"}},{"src":"../assets/voice/sortie/ja/bella_5.mp3","ms":5100,"text":{"ko":"내 환자는 한 명도 두고 가지 않아. 그것만은 기억해 둬.","ja":"あたしの患者は、一人だって置いていかない。それだけは覚えときな。"}}],"dana":[{"src":"../assets/voice/sortie/ja/dana_1.mp3","ms":5010,"text":{"ko":"관측수 다나, 출격합니다. 출격 시각을 기록했습니다.","ja":"観測手のダナ、出撃します。出撃時刻を、記録しました。"}},{"src":"../assets/voice/sortie/ja/dana_2.mp3","ms":5540,"text":{"ko":"탄흔 좌표, 전부 적어 두겠습니다. 한 발도 놓치지 않겠습니다.","ja":"弾痕の座標、すべて書き留めます。一発も、見逃しません。"}},{"src":"../assets/voice/sortie/ja/dana_3.mp3","ms":5070,"text":{"ko":"현장은 제 눈으로 확인하겠습니다. 중열, 배치에 들어갑니다.","ja":"現場は、私の目で確かめます。中列、配置につきます。"}},{"src":"../assets/voice/sortie/ja/dana_4.mp3","ms":6900,"text":{"ko":"누가, 언제, 어디서 싸웠는지. 전부 현재로 남기겠습니다.","ja":"誰が、いつ、どこで戦ったか。全部、現在として残します。"}},{"src":"../assets/voice/sortie/ja/dana_5.mp3","ms":4920,"text":{"ko":"기록 정정은 전투가 끝난 뒤에. 지금은 쏠 시각입니다.","ja":"記録訂正は、戦闘の後で。今は、撃つ時刻です。"}}],"mei":[{"src":"../assets/voice/sortie/ja/mei_1.mp3","ms":5770,"text":{"ko":"메이, 출격합니다. 후열에서 여러분 이름을 계속 부를게요.","ja":"メイ、出撃します。後列から、皆さんの名前を呼び続けます。"}},{"src":"../assets/voice/sortie/ja/mei_2.mp3","ms":6960,"text":{"ko":"필드 서베이어, 장전 완료입니다. 뒤에 있는 사람들한테는 한 발도 닿게 하지 않겠습니다.","ja":"フィールド・サーベイヤー、装填完了です。後ろの人たちには、一発も届かせません。"}},{"src":"../assets/voice/sortie/ja/mei_3.mp3","ms":5440,"text":{"ko":"후열에 섭니다. 쓰러진 사람 머리맡에는 제가 직접 가겠습니다.","ja":"後列につきます。倒れた人の枕元には、わたしが直接行きます。"}},{"src":"../assets/voice/sortie/ja/mei_4.mp3","ms":6950,"text":{"ko":"이번엔 제가 스스로 정하고 여기 왔어요. 누구한테도 대신 쓰게 하지 않을 거예요.","ja":"今度は、わたしが自分で決めて、ここに来ました。誰にも、代わりに書かせません。"}},{"src":"../assets/voice/sortie/ja/mei_5.mp3","ms":6000,"text":{"ko":"사령관, 약속이에요. 전원, 자기 발로 돌아와 주세요.","ja":"司令官、約束です。全員、自分の足で帰ってきてください。"}}],"yujin":[{"src":"../assets/voice/sortie/ja/yujin_1.mp3","ms":4300,"text":{"ko":"유진, 출격한다. 회랑 하나는 비워 둬라.","ja":"ユジン、出撃する。回廊を一本、空けておけ。"}},{"src":"../assets/voice/sortie/ja/yujin_2.mp3","ms":5540,"text":{"ko":"바스티온 리피터, 회전 양호. 전열은 내가 맡는다.","ja":"バスティオン・リピーター、回転良好。前列は、私が受け持つ。"}},{"src":"../assets/voice/sortie/ja/yujin_3.mp3","ms":6100,"text":{"ko":"들것 스물, 이송 순서도 정해 뒀다. 이제 전원 데리고 돌아가기만 하면 된다.","ja":"担架二十、搬送の順番も決めてある。あとは全員、連れて帰るだけだ。"}},{"src":"../assets/voice/sortie/ja/yujin_4.mp3","ms":6970,"text":{"ko":"떨어지는 것 아래에 사람은 남기지 않는다. 적을 치우는 건 그다음이면 된다.","ja":"落ちてくるものの下に、人は残さない。敵を片付けるのは、その後でいい。"}},{"src":"../assets/voice/sortie/ja/yujin_5.mp3","ms":8120,"text":{"ko":"사령관, 돌아갈 길은 내가 비워 둔다. 당신은 앞을 봐라. 인원수만은 줄이지 마라.","ja":"司令官、帰り道は私が空けておく。あなたは前を見ていろ。人数だけは、減らすな。"}}],"iona":[{"src":"../assets/voice/sortie/ja/iona_1.mp3","ms":4220,"text":{"ko":"이오나 렉스, 나간다. 정면은 내가 연다.","ja":"イオナ・レックス、出る。正面は、あたしがこじ開ける。"}},{"src":"../assets/voice/sortie/ja/iona_2.mp3","ms":5290,"text":{"ko":"렉스 하모닉 엣지, 공명 양호. 과열되기 전에 밀어붙인다.","ja":"レックス・ハーモニック・エッジ、共鳴よし。過熱する前に、押し切る。"}},{"src":"../assets/voice/sortie/ja/iona_3.mp3","ms":4460,"text":{"ko":"중열에 선다. 앞이 막히면 내가 옆에서 쓸어버린다.","ja":"中列につく。前が詰まったら、あたしが横から薙ぎ払う。"}},{"src":"../assets/voice/sortie/ja/iona_4.mp3","ms":4060,"text":{"ko":"임무 코드가 아니다. 오늘도 내 이름으로 쏜다.","ja":"任務コードじゃない。今日も、あたしの名前で撃つ。"}},{"src":"../assets/voice/sortie/ja/iona_5.mp3","ms":5290,"text":{"ko":"사령관, 내가 너무 밀고 들어가면 불러 세워. 그 목소리만큼은 듣는다.","ja":"司令官、あたしが突っ込みすぎたら、呼び止めろ。その声だけは聞く。"}}],"harin":[{"src":"../assets/voice/sortie/ja/harin_1.mp3","ms":5490,"text":{"ko":"하린, 출격합니다. 전열 보호는 제가 맡겠습니다.","ja":"ハリン、出撃します。前列の保護は、私が引き受けます。"}},{"src":"../assets/voice/sortie/ja/harin_2.mp3","ms":6010,"text":{"ko":"커스터디 브리치, 장전했습니다. 쏘는 범위는 규정대로 기록하겠습니다.","ja":"カストディ・ブリーチ、装填しました。撃つ範囲は、規定どおりに記録します。"}},{"src":"../assets/voice/sortie/ja/harin_3.mp3","ms":8130,"text":{"ko":"전열에 섭니다. 예외가 필요한 분은 제 뒤로. 보호 조건은 나중에 여쭙겠습니다.","ja":"前列につきます。例外が必要な方は、私の後ろへ。保護条件は、あとで伺います。"}},{"src":"../assets/voice/sortie/ja/harin_4.mp3","ms":6640,"text":{"ko":"효력 없는 명령으로 이름을 지우게 두지 않겠습니다. 그 칸은 보류로 남겨 둡니다.","ja":"効力のない命令で、名前を消させはしません。その欄は、保留のままです。"}},{"src":"../assets/voice/sortie/ja/harin_5.mp3","ms":6730,"text":{"ko":"사령관, 귀환 기록은 제가 적겠습니다. 빈칸으로 두지 말아 주십시오.","ja":"司令官、帰還記録は私が付けます。空欄のままにはしないでください。"}}],"lumi":[{"src":"../assets/voice/sortie/ja/lumi_1.mp3","ms":4690,"text":{"ko":"루미, 출격! 조명은 필요 없어. 카운트만 들어.","ja":"ルミ、出撃！　照明はいらない、カウントだけ聞いて。"}},{"src":"../assets/voice/sortie/ja/lumi_2.mp3","ms":5400,"text":{"ko":"페이즈 앵커, 고정 완료. 전열 리듬은 내가 새긴다.","ja":"フェイズ・アンカー、固定完了。前列のリズムは、わたしが刻む。"}},{"src":"../assets/voice/sortie/ja/lumi_3.mp3","ms":5280,"text":{"ko":"전열에 선다. 셋 세면 전원 각자 판단으로 움직여.","ja":"前列につくよ。三つ数えたら、全員それぞれの判断で動いて。"}},{"src":"../assets/voice/sortie/ja/lumi_4.mp3","ms":5630,"text":{"ko":"정답 안무 같은 건 없어. 그래도 한 명도 두고 가지 않아.","ja":"正解の振り付けなんてない。それでも、ひとりも置いていかない。"}},{"src":"../assets/voice/sortie/ja/lumi_5.mp3","ms":6400,"text":{"ko":"사령관님, 같이 호흡 맞춰 주세요. 넷 세면 막을 올릴게요!","ja":"司令官、一緒に呼吸を合わせてください。四つ数えたら、幕を上げます！"}}],"yumi":[{"src":"../assets/voice/sortie/ja/yumi_1.mp3","ms":5050,"text":{"ko":"유미, 출격한다. 그림자 쪽은 내가 맡는다.","ja":"ユミ、出撃する。影の側は、私が受け持つ。"}},{"src":"../assets/voice/sortie/ja/yumi_2.mp3","ms":4800,"text":{"ko":"어드주디케이터, 바늘 양호. 끊는 건 연결뿐이다.","ja":"アジュディケーター、針よし。切るのは接続だけだ。"}},{"src":"../assets/voice/sortie/ja/yumi_3.mp3","ms":4780,"text":{"ko":"중열에 선다. 두 선은 따로 지킨다.","ja":"中列につく。二本の線は、別々に守る。"}},{"src":"../assets/voice/sortie/ja/yumi_4.mp3","ms":5990,"text":{"ko":"한쪽을 미끼로 쓰는 명령은 안 받는다. 둘 다 데리고 돌아간다.","ja":"片方を囮にする命令は、受けない。どちらも、連れて帰る。"}},{"src":"../assets/voice/sortie/ja/yumi_5.mp3","ms":4940,"text":{"ko":"사령관, 철수선은 6초만 보장한다. ……늦지 마.","ja":"司令官、撤退線は六秒だけ保証する。……遅れるな。"}}],"dabin":[{"src":"../assets/voice/sortie/ja/dabin_1.mp3","ms":4680,"text":{"ko":"다빈, 나간다. 틈은 내가 열고, 진입도 먼저 한다.","ja":"ダビン、出る。隙はあたしが開ける、進入も先にやる。"}},{"src":"../assets/voice/sortie/ja/dabin_2.mp3","ms":4740,"text":{"ko":"페이즈 앵커, 위상 맞춤 완료. 잔상은 둘까지 낼 수 있어.","ja":"フェイズ・アンカー、位相合わせ完了。残像は二つまで出せる。"}},{"src":"../assets/voice/sortie/ja/dabin_3.mp3","ms":4710,"text":{"ko":"전열에 선다. 각도 40, 참호 앞은 내가 막는다.","ja":"前列につく。角度四十、塹壕の前はあたしが塞ぐ。"}},{"src":"../assets/voice/sortie/ja/dabin_4.mp3","ms":4990,"text":{"ko":"이송로는 안 닫히게 한다. 마지막 한 명이 빠질 때까지 내가 뛴다.","ja":"移送路は閉じさせない。最後の一人が抜けるまで、あたしが走る。"}},{"src":"../assets/voice/sortie/ja/dabin_5.mp3","ms":5060,"text":{"ko":"사령관, 합류 신호만 줘. 나머진 내가 알아서 돌아 들어간다.","ja":"司令官、合流の合図だけくれ。あとは、あたしが勝手に回り込む。"}}],"sion":[{"src":"../assets/voice/sortie/ja/sion_1.mp3","ms":5190,"text":{"ko":"시온, 출격. 공구는 두고 간다. 오늘은 이걸로 고친다.","ja":"シオン、出撃。工具は置いてく、今日はこっちで直す。"}},{"src":"../assets/voice/sortie/ja/sion_2.mp3","ms":7830,"text":{"ko":"포지 브레이커, 코일 압력 양호. 과열 한계 91, 그 이상은 안 돌린다.","ja":"フォージ・ブレイカー、コイル圧力よし。過熱限界は九十一、それ以上は回さない。"}},{"src":"../assets/voice/sortie/ja/sion_3.mp3","ms":4770,"text":{"ko":"중열에 선다. 멈추는 순서는 내가 말할게. 역순이야.","ja":"中列につく。止める順番は、あたしが言う。逆からだ。"}},{"src":"../assets/voice/sortie/ja/sion_4.mp3","ms":6080,"text":{"ko":"코어랑 장갑은 따로 쏜다. 한꺼번에 부수면 고칠 수 있는 것까지 없어져.","ja":"コアと装甲は、分けて撃つ。まとめて壊すと、直せるものまで無くなる。"}},{"src":"../assets/voice/sortie/ja/sion_5.mp3","ms":8200,"text":{"ko":"사령관, 탄 배선은 우회할 수 있어. 근데 사람은 우회 못 해. 무리한 순서는 짜지 마.","ja":"司令官、焼けた配線は迂回できる。でも、人は迂回できない。無茶な順番は組まないで。"}}],"liora":[{"src":"../assets/voice/sortie/ja/liora_1.mp3","ms":8040,"text":{"ko":"리오라 크레스트, 출격하겠습니다. 이번 호위 대상은 제 뒤에 선 대원 전원입니다.","ja":"リオラ・クレスト、出撃いたします。今回の護衛対象は、私の後ろに立つ隊員全員です。"}},{"src":"../assets/voice/sortie/ja/liora_2.mp3","ms":8270,"text":{"ko":"크레스트 커스터디, 문장 봉인 장전. 방패로 빛을 흩고 창끝으로 길을 열겠습니다.","ja":"クレスト・カストディ、紋章の封印を装填。盾で光を散らし、槍の穂先で道を開きます。"}},{"src":"../assets/voice/sortie/ja/liora_3.mp3","ms":8280,"text":{"ko":"전열에 서겠습니다. 탄은 제 방패로 막겠습니다. 여러분은 사선만 지켜 주십시오.","ja":"前列をお引き受けいたします。弾は私の盾が受けます。皆さんは、射線だけを守ってください。"}},{"src":"../assets/voice/sortie/ja/liora_4.mp3","ms":10530,"text":{"ko":"끝까지 선다는 말은 혼자 남겠다는 뜻이 아닙니다. 버거우면 교대를 요청하십시오. 저도 그렇게 하겠습니다.","ja":"最後まで立つとは、独りで残るという意味ではありません。苦しければ、交代を要請してください。私もそういたします。"}},{"src":"../assets/voice/sortie/ja/liora_5.mp3","ms":8490,"text":{"ko":"사령관님, 명령은 사령관님이 내리십시오. 그 명령이 누구를 지키는지는 제가 끝까지 확인하겠습니다.","ja":"司令官、ご命令は司令官が。その命令が誰を守るものなのかは、私が最後まで確かめます。"}}],"seorin":[{"src":"../assets/voice/sortie/ja/seorin_1.mp3","ms":5780,"text":{"ko":"서린, 출격합니다. 후열에서 모두의 맥을 잇겠습니다.","ja":"ソリン、出撃します。後列から、皆さんの脈をつなぎます。"}},{"src":"../assets/voice/sortie/ja/seorin_2.mp3","ms":7320,"text":{"ko":"콰이어 이미터, 공명 주파수 조율 완료. 치유 파장은 한 갈래씩 보냅니다.","ja":"クワイア・エミッター、共鳴周波数の調律完了。治療の波は、一本ずつ送ります。"}},{"src":"../assets/voice/sortie/ja/seorin_3.mp3","ms":7110,"text":{"ko":"후열에 서겠습니다. 다치시면 이름으로 불러 주세요. 번호로는 찾지 않을게요.","ja":"後列につきます。怪我をしたら、名前で呼んでください。番号では探しませんから。"}},{"src":"../assets/voice/sortie/ja/seorin_4.mp3","ms":7670,"text":{"ko":"공명이 너무 깊어지면 제가 먼저 끊겠습니다. 돌아올 통로는 제가 지킬게요.","ja":"共鳴が深くなりすぎたら、わたしが先に切ります。戻る通り道は、わたしが守ります。"}},{"src":"../assets/voice/sortie/ja/seorin_5.mp3","ms":6570,"text":{"ko":"사령관님, 명령은 한 갈래씩 주세요. 그래야 모두가 따라올 수 있어요.","ja":"司令官、命令は一本ずつください。そうすれば、みんながついて来られます。"}}],"eve":[{"src":"../assets/voice/sortie/ja/eve_1.mp3","ms":7570,"text":{"ko":"이브 녹턴, 나간다. 불빛 줄여. 먼저 보이는 쪽이 먼저 죽는다.","ja":"イヴ・ノクターン、出る。明かりを落とせ。先に見られた方が、先に死ぬ。"}},{"src":"../assets/voice/sortie/ja/eve_2.mp3","ms":5270,"text":{"ko":"녹턴 하모닉 윙, 날개 안테나 전개. 공명 주파수 고정.","ja":"ノクターン・ハーモニック・ウィング、翼のアンテナ展開。共鳴周波数、固定。"}},{"src":"../assets/voice/sortie/ja/eve_3.mp3","ms":6170,"text":{"ko":"그림자 쪽에 선다. 사선은 하나면 돼. 내가 긋는다.","ja":"影の側につく。射線は一本でいい。私が引く。"}},{"src":"../assets/voice/sortie/ja/eve_4.mp3","ms":5840,"text":{"ko":"신호가 끊겨도 당황하지 마. 끊긴 자리가 우리가 숨을 자리다.","ja":"信号が切れても慌てるな。切れた場所が、私たちの隠れ場所だ。"}},{"src":"../assets/voice/sortie/ja/eve_5.mp3","ms":6730,"text":{"ko":"사령관, 명령은 짧게. 긴 말은 잔광을 남긴다.","ja":"司令官、命令は短く。長い言葉は、残光を残す。"}}],"chaerin":[{"src":"../assets/voice/sortie/ja/chaerin_1.mp3","ms":6520,"text":{"ko":"채린, 출격합니다. 퇴로 셋 확보. 들어갈 때부터 나올 길을 봐 두세요.","ja":"チェリン、出撃します。退路三本、確保。入るときから、出る道を見ておいてください。"}},{"src":"../assets/voice/sortie/ja/chaerin_2.mp3","ms":6830,"text":{"ko":"실 포인터, 아크 충전 완료. 제가 표시한 자리에 맞춰서 쏴 주세요.","ja":"シール・ポインター、アーク充電完了。わたしが印をつけた所に、合わせて撃ってください。"}},{"src":"../assets/voice/sortie/ja/chaerin_3.mp3","ms":7320,"text":{"ko":"후열에 설게요. 호흡 맞춰요. 셋에 교대, 다음은 제가 받을게요.","ja":"後列につきます。呼吸、合わせましょう。三つで交代、次はわたしが受けます。"}},{"src":"../assets/voice/sortie/ja/chaerin_4.mp3","ms":7130,"text":{"ko":"길이 두 개 끊겨도 당황하지 마세요. 남은 한 가닥으로 사람부터 내보낼게요.","ja":"道が二本切れても、慌てないでください。残った一本で、人から先に出します。"}},{"src":"../assets/voice/sortie/ja/chaerin_5.mp3","ms":6190,"text":{"ko":"사령관, 앞은 맡길게요. 뒤는 제가 끝까지 열어 둘게요.","ja":"司令官、前はお任せします。後ろは、わたしが最後まで開けておきます。"}}],"soha":[{"src":"../assets/voice/sortie/ja/soha_1.mp3","ms":5460,"text":{"ko":"소하, 출격한다. 먼저 간 사람들이 놓친 사각은 내가 챙긴다.","ja":"ソハ、出るよ。先に行った連中が見落とした死角、あたしが拾う。"}},{"src":"../assets/voice/sortie/ja/soha_2.mp3","ms":7090,"text":{"ko":"하모닉 라이플, 레일 둘 다 맞췄어. 조준은 늦게, 명중은 정확하게.","ja":"ハーモニック・ライフル、レール二本とも揃えた。狙うのは遅く、当てるのは正確に。"}},{"src":"../assets/voice/sortie/ja/soha_3.mp3","ms":7830,"text":{"ko":"중열은 내가 지킨다. 앞줄이 못 보는 옆길은 불러 줄게. 들리면 바로 돌아봐.","ja":"中列を受け持つ。前列が見えない脇道は、あたしが呼ぶ。聞こえたら、すぐ振り向いて。"}},{"src":"../assets/voice/sortie/ja/soha_4.mp3","ms":5750,"text":{"ko":"지도에 없는 길로 온다고? 좋아. 지도에 없는 길은 내 담당이야.","ja":"地図にない道から来るって？　いいよ、地図にない道はあたしの担当だ。"}},{"src":"../assets/voice/sortie/ja/soha_5.mp3","ms":8060,"text":{"ko":"사령관, 퇴로 하나는 내가 비워 둘게. 빈 길이 있어야 늦게 오는 사람도 돌아오지.","ja":"司令官、退路は一本、あたしが空けとく。帰り道がなきゃ、遅れて来たやつも帰って来られない。"}}],"haejin":[{"src":"../assets/voice/sortie/ja/haejin_1.mp3","ms":6180,"text":{"ko":"해진, 출격. 설비 앞에 선다. 부수는 건 적 표식뿐이다.","ja":"ヘジン、出る。設備の前に立つ。壊すのは、敵の標識だけだ。"}},{"src":"../assets/voice/sortie/ja/haejin_2.mp3","ms":8140,"text":{"ko":"플레이트 고정. 좌우 간격 확인. 탄은 서른네 발, 세 번에 나눠 쓴다.","ja":"プレート、固定。左右の間隔、確認。弾は三十四発、三回に分けて使う。"}},{"src":"../assets/voice/sortie/ja/haejin_3.mp3","ms":6730,"text":{"ko":"엄호 시작. 뒤에서 쏘는 사람은 플레이트 그림자 안으로 들어와라. 바깥은 내 담당이다.","ja":"援護、開始。後ろから撃つ者は、プレートの影に入れ。外側は私の担当だ。"}},{"src":"../assets/voice/sortie/ja/haejin_4.mp3","ms":9970,"text":{"ko":"부수기 전에 먼저 구분한다. 적은 쏘고, 설비는 남긴다. 그게 내 사격이다.","ja":"壊す前に、まず区別する。敵は撃つ。設備は残す。それが私の射撃だ。"}},{"src":"../assets/voice/sortie/ja/haejin_5.mp3","ms":10040,"text":{"ko":"사령관, 밀리면 신호 하나만 줘. 방벽이 버티는 동안 전원 뒤로 뺀다. 그 뒤는 내가 닫는다.","ja":"司令官、押されたら合図をひとつくれ。防壁が持つ間に、全員を下げる。その後ろは、私が閉じる。"}}],"yuria":[{"src":"../assets/voice/sortie/ja/yuria_1.mp3","ms":8750,"text":{"ko":"유리아 글린트, 출격합니다. 인트로 없이 바로 들어가요. 첫 박부터 맞춰 주세요.","ja":"ユリア・グリント、出撃します。イントロなしで、そのまま入ります。最初の拍から合わせてください。"}},{"src":"../assets/voice/sortie/ja/yuria_2.mp3","ms":6580,"text":{"ko":"호흡 트랙 깔게요. 숨 쉴 자리를 비워 둘 테니까, 그 박에 맞춰 쏴 주세요.","ja":"ブレス・トラックを敷きます。息をする場所をあけておきますから、その拍に合わせて撃ってください。"}},{"src":"../assets/voice/sortie/ja/yuria_3.mp3","ms":6980,"text":{"ko":"관객 없는 전장도 무대예요. 박자만 맞추면, 아무도 어긋나지 않아요.","ja":"観客のいない戦場も、舞台です。拍さえ合わせれば、誰もずれません。"}},{"src":"../assets/voice/sortie/ja/yuria_4.mp3","ms":7830,"text":{"ko":"카운트 잡았어요. 여덟 박 뒤에 다 같이 쏩니다. 그때까지는 숨을 아껴 주세요.","ja":"カウントを取りました。八拍後に、全員で一斉に撃ちます。それまでは、息を温存してください。"}},{"src":"../assets/voice/sortie/ja/yuria_5.mp3","ms":9030,"text":{"ko":"사령관님, 돌아오는 길의 카운트도 제가 세어 둘게요. 길을 잃으면 제 박자만 따라오세요.","ja":"司令官、帰り道のカウントも、わたしが数えておきます。道に迷ったら、わたしのビートだけ追ってきてください。"}}],"sea":[{"src":"../assets/voice/sortie/ja/sea_1.mp3","ms":10800,"text":{"ko":"세아, 출격합니다. 부적선은 이미 그어 뒀어요. 선 안쪽에서 움직여 주세요. 안쪽은 제가 지켜요.","ja":"セア、出撃します。札の線は、もう引いてあります。線の内側で動いてください。内側は、わたしが守ります。"}},{"src":"../assets/voice/sortie/ja/sea_2.mp3","ms":9440,"text":{"ko":"콰이어 펄스, 진동 조율 끝났어요. 세게 울리진 않을 거예요. 맥이 놀라지 않을 만큼만요.","ja":"クワイア・パルス、振動の調整、終わりました。強くは鳴らしません。脈が驚かない程度だけです。"}},{"src":"../assets/voice/sortie/ja/sea_3.mp3","ms":6700,"text":{"ko":"왼쪽 맥이 앞서가네요. 반 박만 늦춰 주세요. 오른쪽에 나란히 맞출게요.","ja":"左の脈が先へ行ってますね。半拍だけ遅らせてください。右と並べます。"}},{"src":"../assets/voice/sortie/ja/sea_4.mp3","ms":8780,"text":{"ko":"무리하지 마세요. 손을 드는 건 약한 게 아니에요. 그게 신호예요. 바로 갈게요.","ja":"無理はしないでください。手を挙げるのは、弱いことじゃありません。それが合図です。すぐ行きます。"}},{"src":"../assets/voice/sortie/ja/sea_5.mp3","ms":8540,"text":{"ko":"사령관님, 돌아오시면 물부터 드릴게요. 그러니까 다들, 숨 쉬는 채로 돌아오세요.","ja":"司令官、戻ったら、まずお水をお出ししますね。ですから皆さん、息をしたまま戻ってきてください。"}}]},"ko":{"mira":[{"src":"../assets/voice/sortie/ko/mira_1.mp3","ms":3670,"text":{"ko":"미라 보스, 출격합니다. 링크 접속, 전 대원 응답 확인.","ja":"ミラ・ヴォス、出撃します。リンク接続、全隊員の応答を確認。"}},{"src":"../assets/voice/sortie/ko/mira_2.mp3","ms":5110,"text":{"ko":"후열, 배치에 들어갑니다. 전선의 사선은 제가 보정하겠습니다.","ja":"後列、配置につきます。前線の射線は、私が補正します。"}},{"src":"../assets/voice/sortie/ko/mira_3.mp3","ms":4010,"text":{"ko":"R-0 카빈, 안전장치 해제. 교전을 개시합니다.","ja":"R-0カービン、安全装置解除。交戦を開始します。"}},{"src":"../assets/voice/sortie/ko/mira_4.mp3","ms":5090,"text":{"ko":"작전 범위, 확인했습니다. 전원 귀환을 조건에 추가하겠습니다.","ja":"作戦範囲、確認しました。全員で戻ることを、条件に加えます。"}},{"src":"../assets/voice/sortie/ko/mira_5.mp3","ms":5240,"text":{"ko":"화이트 릴레이, 전개합니다. 지평선 너머까지 신호를 보내겠습니다.","ja":"ホワイト・リレー、展開します。地平線の向こうまで、信号を届けます。"}}],"haneul":[{"src":"../assets/voice/sortie/ko/haneul_1.mp3","ms":3960,"text":{"ko":"하늘-7, 출격. 정비 드론, 전 기체 동행.","ja":"ハヌル-7、出撃。整備ドローン、全機随伴。"}},{"src":"../assets/voice/sortie/ko/haneul_2.mp3","ms":3790,"text":{"ko":"오염률, 측정 개시. 보호 채널, 열어 둘게.","ja":"汚染率、測定開始。保護チャンネル、開いておく。"}},{"src":"../assets/voice/sortie/ko/haneul_3.mp3","ms":3840,"text":{"ko":"중열, 정위치. 적 분리도, 판정 중.","ja":"中列、定位置。敵の分離度、判定中。"}},{"src":"../assets/voice/sortie/ko/haneul_4.mp3","ms":4690,"text":{"ko":"생존 확률, 상승 중. ……정정. 내가 올릴 거야.","ja":"生存確率、上昇中。……訂正。わたしが、上げる。"}},{"src":"../assets/voice/sortie/ko/haneul_5.mp3","ms":4910,"text":{"ko":"사령관, 귀환 지점 등록했어. ……같이 돌아가.","ja":"司令官、帰還地点を登録した。……一緒に、戻る。"}}],"sera":[{"src":"../assets/voice/sortie/ko/sera_1.mp3","ms":5010,"text":{"ko":"세라 플린트, 먼저 나간다. 너희는 내 발자국 밟고 따라와.","ja":"セラ・フリント、先に出るよ。あんたらは、あたしの足跡を踏んで来な。"}},{"src":"../assets/voice/sortie/ko/sera_2.mp3","ms":5810,"text":{"ko":"디지털이 입을 다물어도 분필 선은 안 지워져. 자, 간다.","ja":"デジタルが黙っても、チョーク線は消えない。さあ、行くぞ。"}},{"src":"../assets/voice/sortie/ko/sera_3.mp3","ms":4550,"text":{"ko":"조명탄, 점화 준비 끝. 어두운 데는 전부 내가 비춰 줄게.","ja":"フレア、点火準備よし。暗いところは、全部あたしが照らしてやる。"}},{"src":"../assets/voice/sortie/ko/sera_4.mp3","ms":3970,"text":{"ko":"전열은 나야. 종이 지도는 가슴 주머니에 넣어 뒀어.","ja":"前衛はあたしだ。紙の地図は、胸ポケットに入れてある。"}},{"src":"../assets/voice/sortie/ko/sera_5.mp3","ms":3650,"text":{"ko":"살아서 돌아올 때까지가 작전이잖아. 늦지 마.","ja":"生きて帰るまでが作戦だろ、遅れんなよ。"}}],"astra":[{"src":"../assets/voice/sortie/ko/astra_1.mp3","ms":4170,"text":{"ko":"아스트라 벨, 출격한다. 시야 양호, 오차 없음.","ja":"アストラ・ベル、出撃する。視界良好、誤差なし。"}},{"src":"../assets/voice/sortie/ko/astra_2.mp3","ms":2930,"text":{"ko":"탄도, 계산 완료. 첫 발부터 맞힌다.","ja":"弾道、計算済み。一発目から当てる。"}},{"src":"../assets/voice/sortie/ko/astra_3.mp3","ms":3540,"text":{"ko":"중열에서 전역을 관측한다. 사각은 내가 메운다.","ja":"中列から全域を観測する。死角は、私が埋める。"}},{"src":"../assets/voice/sortie/ko/astra_4.mp3","ms":5390,"text":{"ko":"불명 적영, 하나. 확인할 때까지 쏘지 않는다. 확인하면 빗나가지 않는다.","ja":"不明な敵影、一。確認するまで撃たない。確認したら、外さない。"}},{"src":"../assets/voice/sortie/ko/astra_5.mp3","ms":3820,"text":{"ko":"잔광 각도, 고정. 사령관, 쏠 곳을 지시해라.","ja":"残光の角度、固定。司令官、撃つ場所を示せ。"}}],"tessa":[{"src":"../assets/voice/sortie/ko/tessa_1.mp3","ms":3730,"text":{"ko":"테사 룬, 앞으로 나간다. 전열은 내가 받친다.","ja":"テッサ・ルーン、前へ出る。戦列は私が支える。"}},{"src":"../assets/voice/sortie/ko/tessa_2.mp3","ms":3840,"text":{"ko":"방벽 전개. 이 선부터는 아무도 못 지나간다.","ja":"防壁、展開。この線から先には、誰も通さない。"}},{"src":"../assets/voice/sortie/ko/tessa_3.mp3","ms":4520,"text":{"ko":"교대 순서는 정해 뒀다. 쓰러지기 전에 물린다.","ja":"交代の順番は決めてある。倒れる前に、下がらせる。"}},{"src":"../assets/voice/sortie/ko/tessa_4.mp3","ms":4080,"text":{"ko":"파운드리 헤비, 장전 완료. 엄호 사격 개시한다.","ja":"ファウンドリ・ヘビー、装填完了。援護射撃、開始する。"}},{"src":"../assets/voice/sortie/ko/tessa_5.mp3","ms":3480,"text":{"ko":"전원 돌아간다. 그게 오늘의 약속이다.","ja":"全員で帰る。それが、今日の約束だ。"}}],"naru":[{"src":"../assets/voice/sortie/ko/naru_1.mp3","ms":4340,"text":{"ko":"나루 세이건, 출격합니다. 다치면 바로 불러 주세요.","ja":"ナル・セーガン、出撃します。怪我をしたら、すぐに呼んでくださいね。"}},{"src":"../assets/voice/sortie/ko/naru_2.mp3","ms":4710,"text":{"ko":"후열에서 모두의 맥을 보고 있어요. 무리만은 하지 마세요.","ja":"後列から、全員の脈を見ています。無理だけは、しないで。"}},{"src":"../assets/voice/sortie/ko/naru_3.mp3","ms":7080,"text":{"ko":"생존의 연속성, 확보하겠습니다. 한 명도 끊기게 두지 않아요.","ja":"生存の連続性、確保します。一人も、途切れさせません。"}},{"src":"../assets/voice/sortie/ko/naru_4.mp3","ms":3960,"text":{"ko":"붕대도 지혈대도 다 챙겼어요. 안심하고 앞으로 나가세요.","ja":"包帯も止血帯も、揃っています。安心して、前に出てください。"}},{"src":"../assets/voice/sortie/ko/naru_5.mp3","ms":5740,"text":{"ko":"쓰러진 사람은 반드시 데리고 돌아옵니다. 그게 제 싸움 방식이에요.","ja":"倒れた人は、必ず連れて帰ります。それが、私の戦い方です。"}}],"karin":[{"src":"../assets/voice/sortie/ko/karin_1.mp3","ms":3000,"text":{"ko":"알겠습니다. 카린 베가, 출격합니다.","ja":"了解。カリン・ヴェガ、出撃します。"}},{"src":"../assets/voice/sortie/ko/karin_2.mp3","ms":3490,"text":{"ko":"후방 방벽, 전개합니다. 퇴로는 제가 확보하겠습니다.","ja":"後方防壁、展開します。退路は、私が確保します。"}},{"src":"../assets/voice/sortie/ko/karin_3.mp3","ms":4290,"text":{"ko":"파운드리 중탄, 장전. 엄호 사격, 언제든 가능합니다.","ja":"ファウンドリ重弾、装填。援護射撃、いつでもいけます。"}},{"src":"../assets/voice/sortie/ko/karin_4.mp3","ms":5730,"text":{"ko":"맹세는 벽입니다. 오늘도 뒤에 선 사람들을 지키겠습니다.","ja":"誓いは壁です。今日も、後ろに立つ人を守ります。"}},{"src":"../assets/voice/sortie/ko/karin_5.mp3","ms":4750,"text":{"ko":"회수할 때까지 누구 하나 두고 가지 않겠습니다. 명령을 내려 주십시오.","ja":"回収まで、誰ひとり置いていきません。命令を、どうぞ。"}}],"serin":[{"src":"../assets/voice/sortie/ko/serin_1.mp3","ms":2800,"text":{"ko":"세린, 나간다. 좌표 확정.","ja":"セリン、出る。座標、確定。"}},{"src":"../assets/voice/sortie/ko/serin_2.mp3","ms":4160,"text":{"ko":"후열에서 사선을 교차시킨다. 1도의 오차도 허용하지 않는다.","ja":"後列から射線を交差させる。一度のずれも、許さない。"}},{"src":"../assets/voice/sortie/ko/serin_3.mp3","ms":3830,"text":{"ko":"외곽 봉쇄선 전개. 도주로는 남기지 않는다.","ja":"外周の封鎖線、展開。逃げ道は、残さない。"}},{"src":"../assets/voice/sortie/ko/serin_4.mp3","ms":3820,"text":{"ko":"지키기로 한 상대는 지킨다. 이유는 그걸로 충분하다.","ja":"守ると決めた相手は守る。理由は、それで十分だ。"}},{"src":"../assets/voice/sortie/ko/serin_5.mp3","ms":4330,"text":{"ko":"삼각 봉인, 준비 완료. 사령관, 사격 허가를.","ja":"三角封印、準備完了。司令官、射撃許可を。"}}],"luna":[{"src":"../assets/voice/sortie/ko/luna_1.mp3","ms":4430,"text":{"ko":"루나, 출격합니다. 문턱을 넘기 전에 한 호흡.","ja":"ルナ、出撃します。敷居を越える前に、一呼吸。"}},{"src":"../assets/voice/sortie/ko/luna_2.mp3","ms":5290,"text":{"ko":"전열의 벽은 제가 맡겠습니다. 뒤에 계신 분들은 호흡을 고르세요.","ja":"前列の壁は、私が務めます。後ろの方は、呼吸を整えてください。"}},{"src":"../assets/voice/sortie/ko/luna_3.mp3","ms":4700,"text":{"ko":"돌아올 길은 이미 확인해 두었습니다. 안심하고 나아가죠.","ja":"戻り道は、もう確かめてあります。安心して進みましょう。"}},{"src":"../assets/voice/sortie/ko/luna_4.mp3","ms":4050,"text":{"ko":"파운드리 월, 전개. 여기를 돌아올 곳으로 만들겠습니다.","ja":"ファウンドリ・ウォール、展開。ここを、帰る場所にします。"}},{"src":"../assets/voice/sortie/ko/luna_5.mp3","ms":4600,"text":{"ko":"의식은 모두가 돌아와야 끝납니다. 자, 시작하죠.","ja":"儀式は、全員が戻って終わりです。さあ、始めましょう。"}}],"arin":[{"src":"../assets/voice/sortie/ko/arin_1.mp3","ms":3690,"text":{"ko":"아린, 출격합니다. 주석 카드는 전부 챙겼습니다.","ja":"アリン、出撃します。注釈カードは、全部持ちました。"}},{"src":"../assets/voice/sortie/ko/arin_2.mp3","ms":5390,"text":{"ko":"작전이라는 가설을 이제 검증하겠습니다. 반례는 현장에서 찾죠.","ja":"作戦という仮説を、これから検証します。反例は、現場で探しましょう。"}},{"src":"../assets/voice/sortie/ko/arin_3.mp3","ms":4090,"text":{"ko":"드론 제어식, 기동. 변수는 전부 공개하겠습니다.","ja":"ドローン制御式、起動。変数は、すべて公開します。"}},{"src":"../assets/voice/sortie/ko/arin_4.mp3","ms":4980,"text":{"ko":"적 분류는 아직 가설입니다. 확인하면서 나아갈게요.","ja":"敵の分類は、まだ仮説です。確かめながら進みますね。"}},{"src":"../assets/voice/sortie/ko/arin_5.mp3","ms":4980,"text":{"ko":"사령관님의 판단식, 확실히 받았습니다. 제가 증명해 보이겠습니다.","ja":"司令官の判断式、確かに受け取りました。私が、証明してみせます。"}}],"jaein":[{"src":"../assets/voice/sortie/ko/jaein_1.mp3","ms":4000,"text":{"ko":"재인 복스, 출격! 라이브 시간이야!","ja":"ジェイン・ヴォックス、出撃！　ライブの時間だよ！"}},{"src":"../assets/voice/sortie/ko/jaein_2.mp3","ms":4670,"text":{"ko":"드론들, 코러스 배치! 적의 리듬, 전부 무너뜨리자.","ja":"ドローンたち、コーラス配置！　敵のリズム、全部崩しちゃおう。"}},{"src":"../assets/voice/sortie/ko/jaein_3.mp3","ms":4510,"text":{"ko":"후열에서 비트를 새길게. 너희는 그 템포로 달려.","ja":"後列からビートを刻むよ。きみたちは、そのテンポで走って。"}},{"src":"../assets/voice/sortie/ko/jaein_4.mp3","ms":3960,"text":{"ko":"내 목소리가 닿는 한, 이 전장은 내 무대니까.","ja":"わたしの声が届く限り、この戦場は、わたしのステージだから。"}},{"src":"../assets/voice/sortie/ko/jaein_5.mp3","ms":3340,"text":{"ko":"카운트 간다, 원, 투, 쓰리! 출격!","ja":"カウント行くよ、ワン、ツー、スリー！　出撃！"}}],"roa":[{"src":"../assets/voice/sortie/ko/roa_1.mp3","ms":3500,"text":{"ko":"로아, 출격할게! 코일 예열은 완벽해.","ja":"ロア、出撃するよ！　コイルの予熱は、ばっちり。"}},{"src":"../assets/voice/sortie/ko/roa_2.mp3","ms":4300,"text":{"ko":"포지 오버드라이브, 풀가동! 오늘 이 녀석, 기분 좋네.","ja":"フォージ・オーバードライブ、全開！　今日のこいつは、機嫌がいいね。"}},{"src":"../assets/voice/sortie/ko/roa_3.mp3","ms":4760,"text":{"ko":"망가지면 그 자리에서 용접할게. 그러니까 앞만 봐도 돼.","ja":"壊れたら、その場で溶接する。だから、前だけ見てていいよ。"}},{"src":"../assets/voice/sortie/ko/roa_4.mp3","ms":4920,"text":{"ko":"과열 볼트, 장전 완료! 볼트 하나까지 전부 써 버릴 거야.","ja":"過熱ボルト、装填完了！　ボルト一本まで、全部使い切ってやる。"}},{"src":"../assets/voice/sortie/ko/roa_5.mp3","ms":4450,"text":{"ko":"돌아오면 다들 장비 점검할 거야. 부숴도 되니까, 살아서만 돌아와.","ja":"帰ったら、みんなの装備を点検するからね。壊してもいいけど、生きて帰ってよ。"}}],"noella":[{"src":"../assets/voice/sortie/ko/noella_1.mp3","ms":6930,"text":{"ko":"노엘라 크로스, 출격하겠습니다. 모두의 무사를 기도하고 있습니다.","ja":"ノエラ・クロス、出撃いたします。皆さんの無事を、祈っています。"}},{"src":"../assets/voice/sortie/ko/noella_2.mp3","ms":4260,"text":{"ko":"오늘의 싸움도 제가 증인으로 끝까지 지켜보겠습니다.","ja":"今日の戦いも、私が証人として見届けます。"}},{"src":"../assets/voice/sortie/ko/noella_3.mp3","ms":5340,"text":{"ko":"십자 봉인탄, 장전했습니다. 용서와는 별개로, 쏠 것은 쏩니다.","ja":"十字の封印弾、装填しました。赦しとは別に、撃つべきものは撃ちます。"}},{"src":"../assets/voice/sortie/ko/noella_4.mp3","ms":5510,"text":{"ko":"후열에서 여러분의 등을 지켜보고 있어요. 돌아보지 않으셔도 괜찮습니다.","ja":"後列から、皆さんの背中を見ています。振り返らなくても、大丈夫です。"}},{"src":"../assets/voice/sortie/ko/noella_5.mp3","ms":6620,"text":{"ko":"남겨진 이들의 증언을 여기서 끝나게 두지 않겠습니다. 자, 가시죠.","ja":"残された人の証言を、ここで終わらせはしません。さあ、参りましょう。"}}],"ria":[{"src":"../assets/voice/sortie/ko/ria_1.mp3","ms":4110,"text":{"ko":"리아, 선봉에 선다! 돌파구는 내가 연다.","ja":"リア、先陣を切る！　突破口は、あたしが開ける。"}},{"src":"../assets/voice/sortie/ko/ria_2.mp3","ms":3380,"text":{"ko":"곧장 가서 곧장 뚫는다. 뒤는 따라와.","ja":"まっすぐ行って、まっすぐ抜く。後ろは、ついて来い。"}},{"src":"../assets/voice/sortie/ko/ria_3.mp3","ms":6470,"text":{"ko":"펄스 랜스, 충전 완료! 정면의 문을 억지로 열어 주지.","ja":"パルスランス、充填完了！　正面の扉を、こじ開けてやる。"}},{"src":"../assets/voice/sortie/ko/ria_4.mp3","ms":4980,"text":{"ko":"등은 맡겼어. 그러니까 난 뒤돌아보지 않아.","ja":"背中は預けた。だから、あたしは振り返らない。"}},{"src":"../assets/voice/sortie/ko/ria_5.mp3","ms":2880,"text":{"ko":"중앙을 연다. 사령관, 신호를 줘.","ja":"中央を開ける。司令官、合図をくれ。"}}],"bomin":[{"src":"../assets/voice/sortie/ko/bomin_1.mp3","ms":3170,"text":{"ko":"보민, 출격합니다. 잔탄 확인했습니다.","ja":"ボミン、出撃します。残弾、確認しました。"}},{"src":"../assets/voice/sortie/ko/bomin_2.mp3","ms":5620,"text":{"ko":"쏘기 전에 세 번 확인하겠습니다. ……그래도 늦지는 않겠습니다.","ja":"撃つ前に、三回確かめます。……でも、遅れはしません。"}},{"src":"../assets/voice/sortie/ko/bomin_3.mp3","ms":4820,"text":{"ko":"사격선, 유지하겠습니다. 아군 앞에는 한 발도 떨어뜨리지 않겠습니다.","ja":"射撃線、維持します。味方の前には、一発も落としません。"}},{"src":"../assets/voice/sortie/ko/bomin_4.mp3","ms":4660,"text":{"ko":"레일 충전 완료. 사각 확인, 끝났습니다.","ja":"レール、充電完了。死角の確認、終わりました。"}},{"src":"../assets/voice/sortie/ko/bomin_5.mp3","ms":4080,"text":{"ko":"오늘도 오발 제로로 돌아오겠습니다. 약속입니다.","ja":"今日も誤射ゼロで帰ります、約束です。"}}],"orin":[{"src":"../assets/voice/sortie/ko/orin_1.mp3","ms":3920,"text":{"ko":"오린 베일, 출격한다. 심리를 개시한다.","ja":"オリン・ヴェイル、出撃する。審理を開始する。"}},{"src":"../assets/voice/sortie/ko/orin_2.mp3","ms":4660,"text":{"ko":"증거를 모아라. 판결은 그 뒤에 내린다.","ja":"証拠を集めよ。判決は、その後で下す。"}},{"src":"../assets/voice/sortie/ko/orin_3.mp3","ms":3760,"text":{"ko":"어드주디케이터, 장전. 집행 준비는 끝났다.","ja":"アジュディケーター、装填。執行の準備は整った。"}},{"src":"../assets/voice/sortie/ko/orin_4.mp3","ms":5010,"text":{"ko":"적의 이의는 받아들이지 않는다. 효력을 정지한다.","ja":"敵の異議は、認めない。効力を停止する。"}},{"src":"../assets/voice/sortie/ko/orin_5.mp3","ms":2790,"text":{"ko":"사령관, 그대의 명령을 이 작전의 판결로 삼는다.","ja":"司令官、君の命令を、この作戦の判決とする。"}}],"yunseo":[{"src":"../assets/voice/sortie/ko/yunseo_1.mp3","ms":4130,"text":{"ko":"기록. 출격 개시. 목적, 적성 신호 제거.","ja":"記録。出撃を開始。目的、敵性信号の排除。"}},{"src":"../assets/voice/sortie/ko/yunseo_2.mp3","ms":6070,"text":{"ko":"항목 추가. 대원 수, 확인 완료. 귀환 때도 같은 수를 기록함.","ja":"項目追加。隊員数、確認済み。帰還時も、同じ数を記録する。"}},{"src":"../assets/voice/sortie/ko/yunseo_3.mp3","ms":3950,"text":{"ko":"근거 없는 판정은 하지 않음. 교전하면서 검증함.","ja":"根拠のない判定は、しない。交戦しながら、検証する。"}},{"src":"../assets/voice/sortie/ko/yunseo_4.mp3","ms":3750,"text":{"ko":"판정 표식, 준비 완료. 빈칸은 전장에서 메움.","ja":"判定マーク、準備完了。空白は、戦場で埋める。"}},{"src":"../assets/voice/sortie/ko/yunseo_5.mp3","ms":4030,"text":{"ko":"주석. 이번 기록에는 손실 0이라고 적을 예정.","ja":"注釈。今回の記録には、損失ゼロと書く予定。"}}],"yura":[{"src":"../assets/voice/sortie/ko/yura_1.mp3","ms":4120,"text":{"ko":"유라, 출격할게. 경로는 이미 그려 뒀어.","ja":"ユラ、出撃するよ。ルートは、もう描いてある。"}},{"src":"../assets/voice/sortie/ko/yura_2.mp3","ms":3300,"text":{"ko":"내 뒤로 걸어. 발자국 위라면 안전하니까.","ja":"あたしの後ろを歩いて。足跡の上なら、安全だから。"}},{"src":"../assets/voice/sortie/ko/yura_3.mp3","ms":4340,"text":{"ko":"시야의 빈칸, 세 곳. 우회로로 전부 피해 갈게.","ja":"視界の空白、三か所。迂回路で、全部かわすよ。"}},{"src":"../assets/voice/sortie/ko/yura_4.mp3","ms":3880,"text":{"ko":"길 잃으면 나 불러. 지도는 지금부터 다시 그릴게.","ja":"道に迷ったら、あたしを呼んで。地図は、今から描き直す。"}},{"src":"../assets/voice/sortie/ko/yura_5.mp3","ms":3840,"text":{"ko":"돌아올 길까지 제대로 재 뒀어. 다 같이 돌아가자.","ja":"帰り道まで、ちゃんと測ってある。全員で戻ろう。"}}],"yeonhwa":[{"src":"../assets/voice/sortie/ko/yeonhwa_1.mp3","ms":3460,"text":{"ko":"연화, 출격합니다. 전 채널, 접속 확인했어요.","ja":"ヨンファ、出撃します。全チャンネル、接続を確認しました。"}},{"src":"../assets/voice/sortie/ko/yeonhwa_2.mp3","ms":3840,"text":{"ko":"퇴로 확보는 맡겨 주세요. 귀환선은 제가 지킬게요.","ja":"退路の確保は、任せてください。帰還線は、私が守ります。"}},{"src":"../assets/voice/sortie/ko/yeonhwa_3.mp3","ms":4190,"text":{"ko":"전열에 서겠습니다. 여러분의 목소리, 하나도 놓치지 않을게요.","ja":"前列に立ちます。皆さんの声、ひとつも聞き逃しません。"}},{"src":"../assets/voice/sortie/ko/yeonhwa_4.mp3","ms":4980,"text":{"ko":"앵커 플레이트, 고정. 통신을 분리해서 전장을 정리하겠습니다.","ja":"アンカープレート、固定。通信を分離して、戦場を整理します。"}},{"src":"../assets/voice/sortie/ko/yeonhwa_5.mp3","ms":4690,"text":{"ko":"사령관님의 목소리가 모두에게 닿도록. 중계, 시작하겠습니다.","ja":"司令官の声が、全員に届くように。中継、始めます。"}}],"narae":[{"src":"../assets/voice/sortie/ko/narae_1.mp3","ms":2820,"text":{"ko":"나래, 출격. 사선은 내가 가져간다.","ja":"ナレ、出撃。射線は、あたしがもらう。"}},{"src":"../assets/voice/sortie/ko/narae_2.mp3","ms":4070,"text":{"ko":"탄창, 가득. 먼저 쏘고 먼저 끝낸다.","ja":"マガジン、満タン。先に撃って、先に終わらせる。"}},{"src":"../assets/voice/sortie/ko/narae_3.mp3","ms":4120,"text":{"ko":"제압 연사, 간다! 고개 드는 놈부터 떨군다.","ja":"制圧連射、行くぞ！　頭を上げたやつから、落とす。"}},{"src":"../assets/voice/sortie/ko/narae_4.mp3","ms":4680,"text":{"ko":"연결부는 내가 사수한다. 그러니까 아무도 잃게 두지 않아.","ja":"連結部は、あたしが死守する。だから、誰も失わせない。"}},{"src":"../assets/voice/sortie/ko/narae_5.mp3","ms":4580,"text":{"ko":"속도라면 누구한테도 안 져. 늦지 마, 너희.","ja":"速さなら、誰にも負けない。遅れんなよ、あんたら。"}}],"moa":[{"src":"../assets/voice/sortie/ko/moa_1.mp3","ms":2980,"text":{"ko":"모아, 나간다! 앞은 내가 막는다.","ja":"モア、出るぞ！　前はあたしが止める。"}},{"src":"../assets/voice/sortie/ko/moa_2.mp3","ms":4820,"text":{"ko":"앵커 플레이트, 고정! 이 전열은 한 발짝도 안 물러난다.","ja":"アンカープレート、固定！　この戦列は、一歩も下げない。"}},{"src":"../assets/voice/sortie/ko/moa_3.mp3","ms":4250,"text":{"ko":"하, 탄띠는 넉넉해. 사양 않고 쏴 댈 거야.","ja":"はっ、弾帯はたっぷりある。遠慮なく撃ちまくるぞ。"}},{"src":"../assets/voice/sortie/ko/moa_4.mp3","ms":3050,"text":{"ko":"사선을 막는다. 너희는 내 뒤에서 쏴.","ja":"射線を塞ぐ。あんたらは、あたしの後ろから撃て。"}},{"src":"../assets/voice/sortie/ko/moa_5.mp3","ms":3540,"text":{"ko":"이중 봉쇄선 친다. 여기서부터는 내 방벽이야.","ja":"二重の封鎖線、張るぞ。ここから先は、あたしの防壁だ。"}}],"yumi":[{"src":"../assets/voice/sortie/ko/yumi_1.mp3","ms":3210,"text":{"ko":"유미, 출격한다. 그림자 쪽은 내가 맡는다.","ja":"ユミ、出撃する。影の側は、私が受け持つ。"}},{"src":"../assets/voice/sortie/ko/yumi_2.mp3","ms":4400,"text":{"ko":"어드주디케이터, 바늘 양호. 끊는 건 연결뿐이다.","ja":"アジュディケーター、針よし。切るのは接続だけだ。"}},{"src":"../assets/voice/sortie/ko/yumi_3.mp3","ms":3590,"text":{"ko":"중열에 선다. 두 선은 따로 지킨다.","ja":"中列につく。二本の線は、別々に守る。"}},{"src":"../assets/voice/sortie/ko/yumi_4.mp3","ms":5650,"text":{"ko":"한쪽을 미끼로 쓰는 명령은 안 받는다. 둘 다 데리고 돌아간다.","ja":"片方を囮にする命令は、受けない。どちらも、連れて帰る。"}},{"src":"../assets/voice/sortie/ko/yumi_5.mp3","ms":4090,"text":{"ko":"사령관, 철수선은 6초만 보장한다. ……늦지 마.","ja":"司令官、撤退線は六秒だけ保証する。……遅れるな。"}}],"sion":[{"src":"../assets/voice/sortie/ko/sion_1.mp3","ms":4810,"text":{"ko":"시온, 출격. 공구는 두고 간다. 오늘은 이걸로 고친다.","ja":"シオン、出撃。工具は置いてく、今日はこっちで直す。"}},{"src":"../assets/voice/sortie/ko/sion_2.mp3","ms":5310,"text":{"ko":"포지 브레이커, 코일 압력 양호. 과열 한계 91, 그 이상은 안 돌린다.","ja":"フォージ・ブレイカー、コイル圧力よし。過熱限界は九十一、それ以上は回さない。"}},{"src":"../assets/voice/sortie/ko/sion_3.mp3","ms":4430,"text":{"ko":"중열에 선다. 멈추는 순서는 내가 말할게. 역순이야.","ja":"中列につく。止める順番は、あたしが言う。逆からだ。"}},{"src":"../assets/voice/sortie/ko/sion_4.mp3","ms":4890,"text":{"ko":"코어랑 장갑은 따로 쏜다. 한꺼번에 부수면 고칠 수 있는 것까지 없어져.","ja":"コアと装甲は、分けて撃つ。まとめて壊すと、直せるものまで無くなる。"}},{"src":"../assets/voice/sortie/ko/sion_5.mp3","ms":6180,"text":{"ko":"사령관, 탄 배선은 우회할 수 있어. 근데 사람은 우회 못 해. 무리한 순서는 짜지 마.","ja":"司令官、焼けた配線は迂回できる。でも、人は迂回できない。無茶な順番は組まないで。"}}],"haejin":[{"src":"../assets/voice/sortie/ko/haejin_1.mp3","ms":4560,"text":{"ko":"해진, 출격. 설비 앞에 선다. 부수는 건 적 표식뿐이다.","ja":"ヘジン、出る。設備の前に立つ。壊すのは、敵の標識だけだ。"}},{"src":"../assets/voice/sortie/ko/haejin_2.mp3","ms":5150,"text":{"ko":"플레이트 고정. 좌우 간격 확인. 탄은 서른네 발, 세 번에 나눠 쓴다.","ja":"プレート、固定。左右の間隔、確認。弾は三十四発、三回に分けて使う。"}},{"src":"../assets/voice/sortie/ko/haejin_3.mp3","ms":5830,"text":{"ko":"엄호 시작. 뒤에서 쏘는 사람은 플레이트 그림자 안으로 들어와라. 바깥은 내 담당이다.","ja":"援護、開始。後ろから撃つ者は、プレートの影に入れ。外側は私の担当だ。"}},{"src":"../assets/voice/sortie/ko/haejin_4.mp3","ms":5710,"text":{"ko":"부수기 전에 먼저 구분한다. 적은 쏘고, 설비는 남긴다. 그게 내 사격이다.","ja":"壊す前に、まず区別する。敵は撃つ。設備は残す。それが私の射撃だ。"}},{"src":"../assets/voice/sortie/ko/haejin_5.mp3","ms":7840,"text":{"ko":"사령관, 밀리면 신호 하나만 줘. 방벽이 버티는 동안 전원 뒤로 뺀다. 그 뒤는 내가 닫는다.","ja":"司令官、押されたら合図をひとつくれ。防壁が持つ間に、全員を下げる。その後ろは、私が閉じる。"}}],"eve":[{"src":"../assets/voice/sortie/ko/eve_1.mp3","ms":6820,"text":{"ko":"이브 녹턴, 나간다. 불빛 줄여. 먼저 보이는 쪽이 먼저 죽는다.","ja":"イヴ・ノクターン、出る。明かりを落とせ。先に見られた方が、先に死ぬ。"}},{"src":"../assets/voice/sortie/ko/eve_2.mp3","ms":5070,"text":{"ko":"녹턴 하모닉 윙, 날개 안테나 전개. 공명 주파수 고정.","ja":"ノクターン・ハーモニック・ウィング、翼のアンテナ展開。共鳴周波数、固定。"}},{"src":"../assets/voice/sortie/ko/eve_3.mp3","ms":5040,"text":{"ko":"그림자 쪽에 선다. 사선은 하나면 돼. 내가 긋는다.","ja":"影の側につく。射線は一本でいい。私が引く。"}},{"src":"../assets/voice/sortie/ko/eve_4.mp3","ms":6100,"text":{"ko":"신호가 끊겨도 당황하지 마. 끊긴 자리가 우리가 숨을 자리다.","ja":"信号が切れても慌てるな。切れた場所が、私たちの隠れ場所だ。"}},{"src":"../assets/voice/sortie/ko/eve_5.mp3","ms":6280,"text":{"ko":"사령관, 명령은 짧게. 긴 말은 잔광을 남긴다.","ja":"司令官、命令は短く。長い言葉は、残光を残す。"}}],"sea":[{"src":"../assets/voice/sortie/ko/sea_1.mp3","ms":8730,"text":{"ko":"세아, 출격합니다. 부적선은 이미 그어 뒀어요. 선 안쪽에서 움직여 주세요. 안쪽은 제가 지켜요.","ja":"セア、出撃します。札の線は、もう引いてあります。線の内側で動いてください。内側は、わたしが守ります。"}},{"src":"../assets/voice/sortie/ko/sea_2.mp3","ms":7560,"text":{"ko":"콰이어 펄스, 진동 조율 끝났어요. 세게 울리진 않을 거예요. 맥이 놀라지 않을 만큼만요.","ja":"クワイア・パルス、振動の調整、終わりました。強くは鳴らしません。脈が驚かない程度だけです。"}},{"src":"../assets/voice/sortie/ko/sea_3.mp3","ms":6740,"text":{"ko":"왼쪽 맥이 앞서가네요. 반 박만 늦춰 주세요. 오른쪽에 나란히 맞출게요.","ja":"左の脈が先へ行ってますね。半拍だけ遅らせてください。右と並べます。"}},{"src":"../assets/voice/sortie/ko/sea_4.mp3","ms":7320,"text":{"ko":"무리하지 마세요. 손을 드는 건 약한 게 아니에요. 그게 신호예요. 바로 갈게요.","ja":"無理はしないでください。手を挙げるのは、弱いことじゃありません。それが合図です。すぐ行きます。"}},{"src":"../assets/voice/sortie/ko/sea_5.mp3","ms":5670,"text":{"ko":"사령관님, 돌아오시면 물부터 드릴게요. 그러니까 다들, 숨 쉬는 채로 돌아오세요.","ja":"司令官、戻ったら、まずお水をお出ししますね。ですから皆さん、息をしたまま戻ってきてください。"}}],"seorin":[{"src":"../assets/voice/sortie/ko/seorin_1.mp3","ms":5070,"text":{"ko":"서린, 출격합니다. 후열에서 모두의 맥을 잇겠습니다.","ja":"ソリン、出撃します。後列から、皆さんの脈をつなぎます。"}},{"src":"../assets/voice/sortie/ko/seorin_2.mp3","ms":6250,"text":{"ko":"콰이어 이미터, 공명 주파수 조율 완료. 치유 파장은 한 갈래씩 보냅니다.","ja":"クワイア・エミッター、共鳴周波数の調律完了。治療の波は、一本ずつ送ります。"}},{"src":"../assets/voice/sortie/ko/seorin_3.mp3","ms":6710,"text":{"ko":"후열에 서겠습니다. 다치시면 이름으로 불러 주세요. 번호로는 찾지 않을게요.","ja":"後列につきます。怪我をしたら、名前で呼んでください。番号では探しませんから。"}},{"src":"../assets/voice/sortie/ko/seorin_4.mp3","ms":6280,"text":{"ko":"공명이 너무 깊어지면 제가 먼저 끊겠습니다. 돌아올 통로는 제가 지킬게요.","ja":"共鳴が深くなりすぎたら、わたしが先に切ります。戻る通り道は、わたしが守ります。"}},{"src":"../assets/voice/sortie/ko/seorin_5.mp3","ms":5910,"text":{"ko":"사령관님, 명령은 한 갈래씩 주세요. 그래야 모두가 따라올 수 있어요.","ja":"司令官、命令は一本ずつください。そうすれば、みんながついて来られます。"}}],"lumi":[{"src":"../assets/voice/sortie/ko/lumi_1.mp3","ms":4270,"text":{"ko":"루미, 출격! 조명은 필요 없어. 카운트만 들어.","ja":"ルミ、出撃！　照明はいらない、カウントだけ聞いて。"}},{"src":"../assets/voice/sortie/ko/lumi_2.mp3","ms":4630,"text":{"ko":"페이즈 앵커, 고정 완료. 전열 리듬은 내가 새긴다.","ja":"フェイズ・アンカー、固定完了。前列のリズムは、わたしが刻む。"}},{"src":"../assets/voice/sortie/ko/lumi_3.mp3","ms":4120,"text":{"ko":"전열에 선다. 셋 세면 전원 각자 판단으로 움직여.","ja":"前列につくよ。三つ数えたら、全員それぞれの判断で動いて。"}},{"src":"../assets/voice/sortie/ko/lumi_4.mp3","ms":5310,"text":{"ko":"정답 안무 같은 건 없어. 그래도 한 명도 두고 가지 않아.","ja":"正解の振り付けなんてない。それでも、ひとりも置いていかない。"}},{"src":"../assets/voice/sortie/ko/lumi_5.mp3","ms":5230,"text":{"ko":"사령관님, 같이 호흡 맞춰 주세요. 넷 세면 막을 올릴게요!","ja":"司令官、一緒に呼吸を合わせてください。四つ数えたら、幕を上げます！"}}],"iona":[{"src":"../assets/voice/sortie/ko/iona_1.mp3","ms":3430,"text":{"ko":"이오나 렉스, 나간다. 정면은 내가 연다.","ja":"イオナ・レックス、出る。正面は、あたしがこじ開ける。"}},{"src":"../assets/voice/sortie/ko/iona_2.mp3","ms":4650,"text":{"ko":"렉스 하모닉 엣지, 공명 양호. 과열되기 전에 밀어붙인다.","ja":"レックス・ハーモニック・エッジ、共鳴よし。過熱する前に、押し切る。"}},{"src":"../assets/voice/sortie/ko/iona_3.mp3","ms":3350,"text":{"ko":"중열에 선다. 앞이 막히면 내가 옆에서 쓸어버린다.","ja":"中列につく。前が詰まったら、あたしが横から薙ぎ払う。"}},{"src":"../assets/voice/sortie/ko/iona_4.mp3","ms":4080,"text":{"ko":"임무 코드가 아니다. 오늘도 내 이름으로 쏜다.","ja":"任務コードじゃない。今日も、あたしの名前で撃つ。"}},{"src":"../assets/voice/sortie/ko/iona_5.mp3","ms":4950,"text":{"ko":"사령관, 내가 너무 밀고 들어가면 불러 세워. 그 목소리만큼은 듣는다.","ja":"司令官、あたしが突っ込みすぎたら、呼び止めろ。その声だけは聞く。"}}],"somi":[{"src":"../assets/voice/sortie/ko/somi_1.mp3","ms":4790,"text":{"ko":"소미, 출격합니다! ……기, 긴장되지만 괜찮아요!","ja":"ソミ、出撃します！　……き、緊張してますけど、大丈夫です！"}},{"src":"../assets/voice/sortie/ko/somi_2.mp3","ms":3890,"text":{"ko":"로터리, 회전 개시! 전열, 제가 받치겠습니다!","ja":"ロータリー、回転開始！　前列、わたしが支えます！"}},{"src":"../assets/voice/sortie/ko/somi_3.mp3","ms":5600,"text":{"ko":"중계, 접속했습니다. 여러분의 목소리, 제대로 이어 드릴게요.","ja":"中継、接続しました。皆さんの声、ちゃんと繋ぎます。"}},{"src":"../assets/voice/sortie/ko/somi_4.mp3","ms":3610,"text":{"ko":"무서워도 끊지 않을게요. 끝까지 계속 답하겠습니다!","ja":"怖くても、切りません。最後まで、答え続けます！"}},{"src":"../assets/voice/sortie/ko/somi_5.mp3","ms":3100,"text":{"ko":"보고합니다! 소미, 전투 배치 완료했습니다!","ja":"報告します！　ソミ、戦闘配置につきました！"}}],"mei":[{"src":"../assets/voice/sortie/ko/mei_1.mp3","ms":4800,"text":{"ko":"메이, 출격합니다. 후열에서 여러분 이름을 계속 부를게요.","ja":"メイ、出撃します。後列から、皆さんの名前を呼び続けます。"}},{"src":"../assets/voice/sortie/ko/mei_2.mp3","ms":6770,"text":{"ko":"필드 서베이어, 장전 완료입니다. 뒤에 있는 사람들한테는 한 발도 닿게 하지 않겠습니다.","ja":"フィールド・サーベイヤー、装填完了です。後ろの人たちには、一発も届かせません。"}},{"src":"../assets/voice/sortie/ko/mei_3.mp3","ms":4640,"text":{"ko":"후열에 섭니다. 쓰러진 사람 머리맡에는 제가 직접 가겠습니다.","ja":"後列につきます。倒れた人の枕元には、わたしが直接行きます。"}},{"src":"../assets/voice/sortie/ko/mei_4.mp3","ms":6200,"text":{"ko":"이번엔 제가 스스로 정하고 여기 왔어요. 누구한테도 대신 쓰게 하지 않을 거예요.","ja":"今度は、わたしが自分で決めて、ここに来ました。誰にも、代わりに書かせません。"}},{"src":"../assets/voice/sortie/ko/mei_5.mp3","ms":3760,"text":{"ko":"사령관, 약속이에요. 전원, 자기 발로 돌아와 주세요.","ja":"司令官、約束です。全員、自分の足で帰ってきてください。"}}],"yuria":[{"src":"../assets/voice/sortie/ko/yuria_1.mp3","ms":7020,"text":{"ko":"유리아 글린트, 출격합니다. 인트로 없이 바로 들어가요. 첫 박부터 맞춰 주세요.","ja":"ユリア・グリント、出撃します。イントロなしで、そのまま入ります。最初の拍から合わせてください。"}},{"src":"../assets/voice/sortie/ko/yuria_2.mp3","ms":5430,"text":{"ko":"호흡 트랙 깔게요. 숨 쉴 자리를 비워 둘 테니까, 그 박에 맞춰 쏴 주세요.","ja":"ブレス・トラックを敷きます。息をする場所をあけておきますから、その拍に合わせて撃ってください。"}},{"src":"../assets/voice/sortie/ko/yuria_3.mp3","ms":5990,"text":{"ko":"관객 없는 전장도 무대예요. 박자만 맞추면, 아무도 어긋나지 않아요.","ja":"観客のいない戦場も、舞台です。拍さえ合わせれば、誰もずれません。"}},{"src":"../assets/voice/sortie/ko/yuria_4.mp3","ms":7850,"text":{"ko":"카운트 잡았어요. 여덟 박 뒤에 다 같이 쏩니다. 그때까지는 숨을 아껴 주세요.","ja":"カウントを取りました。八拍後に、全員で一斉に撃ちます。それまでは、息を温存してください。"}},{"src":"../assets/voice/sortie/ko/yuria_5.mp3","ms":7430,"text":{"ko":"사령관님, 돌아오는 길의 카운트도 제가 세어 둘게요. 길을 잃으면 제 박자만 따라오세요.","ja":"司令官、帰り道のカウントも、わたしが数えておきます。道に迷ったら、わたしのビートだけ追ってきてください。"}}],"soha":[{"src":"../assets/voice/sortie/ko/soha_1.mp3","ms":4770,"text":{"ko":"소하, 출격한다. 먼저 간 사람들이 놓친 사각은 내가 챙긴다.","ja":"ソハ、出るよ。先に行った連中が見落とした死角、あたしが拾う。"}},{"src":"../assets/voice/sortie/ko/soha_2.mp3","ms":5130,"text":{"ko":"하모닉 라이플, 레일 둘 다 맞췄어. 조준은 늦게, 명중은 정확하게.","ja":"ハーモニック・ライフル、レール二本とも揃えた。狙うのは遅く、当てるのは正確に。"}},{"src":"../assets/voice/sortie/ko/soha_3.mp3","ms":6220,"text":{"ko":"중열은 내가 지킨다. 앞줄이 못 보는 옆길은 불러 줄게. 들리면 바로 돌아봐.","ja":"中列を受け持つ。前列が見えない脇道は、あたしが呼ぶ。聞こえたら、すぐ振り向いて。"}},{"src":"../assets/voice/sortie/ko/soha_4.mp3","ms":5330,"text":{"ko":"지도에 없는 길로 온다고? 좋아. 지도에 없는 길은 내 담당이야.","ja":"地図にない道から来るって？　いいよ、地図にない道はあたしの担当だ。"}},{"src":"../assets/voice/sortie/ko/soha_5.mp3","ms":6690,"text":{"ko":"사령관, 퇴로 하나는 내가 비워 둘게. 빈 길이 있어야 늦게 오는 사람도 돌아오지.","ja":"司令官、退路は一本、あたしが空けとく。帰り道がなきゃ、遅れて来たやつも帰って来られない。"}}],"liora":[{"src":"../assets/voice/sortie/ko/liora_1.mp3","ms":6190,"text":{"ko":"리오라 크레스트, 출격하겠습니다. 이번 호위 대상은 제 뒤에 선 대원 전원입니다.","ja":"リオラ・クレスト、出撃いたします。今回の護衛対象は、私の後ろに立つ隊員全員です。"}},{"src":"../assets/voice/sortie/ko/liora_2.mp3","ms":7350,"text":{"ko":"크레스트 커스터디, 문장 봉인 장전. 방패로 빛을 흩고 창끝으로 길을 열겠습니다.","ja":"クレスト・カストディ、紋章の封印を装填。盾で光を散らし、槍の穂先で道を開きます。"}},{"src":"../assets/voice/sortie/ko/liora_3.mp3","ms":6240,"text":{"ko":"전열에 서겠습니다. 탄은 제 방패로 막겠습니다. 여러분은 사선만 지켜 주십시오.","ja":"前列をお引き受けいたします。弾は私の盾が受けます。皆さんは、射線だけを守ってください。"}},{"src":"../assets/voice/sortie/ko/liora_4.mp3","ms":9050,"text":{"ko":"끝까지 선다는 말은 혼자 남겠다는 뜻이 아닙니다. 버거우면 교대를 요청하십시오. 저도 그렇게 하겠습니다.","ja":"最後まで立つとは、独りで残るという意味ではありません。苦しければ、交代を要請してください。私もそういたします。"}},{"src":"../assets/voice/sortie/ko/liora_5.mp3","ms":7510,"text":{"ko":"사령관님, 명령은 사령관님이 내리십시오. 그 명령이 누구를 지키는지는 제가 끝까지 확인하겠습니다.","ja":"司令官、ご命令は司令官が。その命令が誰を守るものなのかは、私が最後まで確かめます。"}}],"bella":[{"src":"../assets/voice/sortie/ko/bella_1.mp3","ms":3710,"text":{"ko":"벨라, 나간다. 다친 사람은 나한테 데려와.","ja":"ベラ、出るよ。怪我人は、あたしのところに運びな。"}},{"src":"../assets/voice/sortie/ko/bella_2.mp3","ms":3940,"text":{"ko":"이송 순서는 내가 정해. 불평은 살아서 돌아온 다음에 들을게.","ja":"搬送の順番は、あたしが決める。文句は、生きて帰ってから聞く。"}},{"src":"../assets/voice/sortie/ko/bella_3.mp3","ms":3750,"text":{"ko":"루멘 방호, 전개. 피 나면 바로 말해.","ja":"ルーメン防護、展開。出血したら、すぐ言いな。"}},{"src":"../assets/voice/sortie/ko/bella_4.mp3","ms":5110,"text":{"ko":"자, 전원 건강. ……지금까지는. 그 상태로 돌아와.","ja":"はい、全員健康。……今のところはね。その状態で戻っておいで。"}},{"src":"../assets/voice/sortie/ko/bella_5.mp3","ms":4600,"text":{"ko":"내 환자는 한 명도 두고 가지 않아. 그것만은 기억해 둬.","ja":"あたしの患者は、一人だって置いていかない。それだけは覚えときな。"}}],"dana":[{"src":"../assets/voice/sortie/ko/dana_1.mp3","ms":4180,"text":{"ko":"관측수 다나, 출격합니다. 출격 시각을 기록했습니다.","ja":"観測手のダナ、出撃します。出撃時刻を、記録しました。"}},{"src":"../assets/voice/sortie/ko/dana_2.mp3","ms":4630,"text":{"ko":"탄흔 좌표, 전부 적어 두겠습니다. 한 발도 놓치지 않겠습니다.","ja":"弾痕の座標、すべて書き留めます。一発も、見逃しません。"}},{"src":"../assets/voice/sortie/ko/dana_3.mp3","ms":4110,"text":{"ko":"현장은 제 눈으로 확인하겠습니다. 중열, 배치에 들어갑니다.","ja":"現場は、私の目で確かめます。中列、配置につきます。"}},{"src":"../assets/voice/sortie/ko/dana_4.mp3","ms":5510,"text":{"ko":"누가, 언제, 어디서 싸웠는지. 전부 현재로 남기겠습니다.","ja":"誰が、いつ、どこで戦ったか。全部、現在として残します。"}},{"src":"../assets/voice/sortie/ko/dana_5.mp3","ms":4240,"text":{"ko":"기록 정정은 전투가 끝난 뒤에. 지금은 쏠 시각입니다.","ja":"記録訂正は、戦闘の後で。今は、撃つ時刻です。"}}],"chaerin":[{"src":"../assets/voice/sortie/ko/chaerin_1.mp3","ms":6210,"text":{"ko":"채린, 출격합니다. 퇴로 셋 확보. 들어갈 때부터 나올 길을 봐 두세요.","ja":"チェリン、出撃します。退路三本、確保。入るときから、出る道を見ておいてください。"}},{"src":"../assets/voice/sortie/ko/chaerin_2.mp3","ms":5020,"text":{"ko":"실 포인터, 아크 충전 완료. 제가 표시한 자리에 맞춰서 쏴 주세요.","ja":"シール・ポインター、アーク充電完了。わたしが印をつけた所に、合わせて撃ってください。"}},{"src":"../assets/voice/sortie/ko/chaerin_3.mp3","ms":6010,"text":{"ko":"후열에 설게요. 호흡 맞춰요. 셋에 교대, 다음은 제가 받을게요.","ja":"後列につきます。呼吸、合わせましょう。三つで交代、次はわたしが受けます。"}},{"src":"../assets/voice/sortie/ko/chaerin_4.mp3","ms":6380,"text":{"ko":"길이 두 개 끊겨도 당황하지 마세요. 남은 한 가닥으로 사람부터 내보낼게요.","ja":"道が二本切れても、慌てないでください。残った一本で、人から先に出します。"}},{"src":"../assets/voice/sortie/ko/chaerin_5.mp3","ms":4020,"text":{"ko":"사령관, 앞은 맡길게요. 뒤는 제가 끝까지 열어 둘게요.","ja":"司令官、前はお任せします。後ろは、わたしが最後まで開けておきます。"}}],"yujin":[{"src":"../assets/voice/sortie/ko/yujin_1.mp3","ms":3260,"text":{"ko":"유진, 출격한다. 회랑 하나는 비워 둬라.","ja":"ユジン、出撃する。回廊を一本、空けておけ。"}},{"src":"../assets/voice/sortie/ko/yujin_2.mp3","ms":4620,"text":{"ko":"바스티온 리피터, 회전 양호. 전열은 내가 맡는다.","ja":"バスティオン・リピーター、回転良好。前列は、私が受け持つ。"}},{"src":"../assets/voice/sortie/ko/yujin_3.mp3","ms":5570,"text":{"ko":"들것 스물, 이송 순서도 정해 뒀다. 이제 전원 데리고 돌아가기만 하면 된다.","ja":"担架二十、搬送の順番も決めてある。あとは全員、連れて帰るだけだ。"}},{"src":"../assets/voice/sortie/ko/yujin_4.mp3","ms":5900,"text":{"ko":"떨어지는 것 아래에 사람은 남기지 않는다. 적을 치우는 건 그다음이면 된다.","ja":"落ちてくるものの下に、人は残さない。敵を片付けるのは、その後でいい。"}},{"src":"../assets/voice/sortie/ko/yujin_5.mp3","ms":5820,"text":{"ko":"사령관, 돌아갈 길은 내가 비워 둔다. 당신은 앞을 봐라. 인원수만은 줄이지 마라.","ja":"司令官、帰り道は私が空けておく。あなたは前を見ていろ。人数だけは、減らすな。"}}],"harin":[{"src":"../assets/voice/sortie/ko/harin_1.mp3","ms":3840,"text":{"ko":"하린, 출격합니다. 전열 보호는 제가 맡겠습니다.","ja":"ハリン、出撃します。前列の保護は、私が引き受けます。"}},{"src":"../assets/voice/sortie/ko/harin_2.mp3","ms":5530,"text":{"ko":"커스터디 브리치, 장전했습니다. 쏘는 범위는 규정대로 기록하겠습니다.","ja":"カストディ・ブリーチ、装填しました。撃つ範囲は、規定どおりに記録します。"}},{"src":"../assets/voice/sortie/ko/harin_3.mp3","ms":6780,"text":{"ko":"전열에 섭니다. 예외가 필요한 분은 제 뒤로. 보호 조건은 나중에 여쭙겠습니다.","ja":"前列につきます。例外が必要な方は、私の後ろへ。保護条件は、あとで伺います。"}},{"src":"../assets/voice/sortie/ko/harin_4.mp3","ms":6120,"text":{"ko":"효력 없는 명령으로 이름을 지우게 두지 않겠습니다. 그 칸은 보류로 남겨 둡니다.","ja":"効力のない命令で、名前を消させはしません。その欄は、保留のままです。"}},{"src":"../assets/voice/sortie/ko/harin_5.mp3","ms":6690,"text":{"ko":"사령관, 귀환 기록은 제가 적겠습니다. 빈칸으로 두지 말아 주십시오.","ja":"司令官、帰還記録は私が付けます。空欄のままにはしないでください。"}}],"dabin":[{"src":"../assets/voice/sortie/ko/dabin_1.mp3","ms":4210,"text":{"ko":"다빈, 나간다. 틈은 내가 열고, 진입도 먼저 한다.","ja":"ダビン、出る。隙はあたしが開ける、進入も先にやる。"}},{"src":"../assets/voice/sortie/ko/dabin_2.mp3","ms":4050,"text":{"ko":"페이즈 앵커, 위상 맞춤 완료. 잔상은 둘까지 낼 수 있어.","ja":"フェイズ・アンカー、位相合わせ完了。残像は二つまで出せる。"}},{"src":"../assets/voice/sortie/ko/dabin_3.mp3","ms":3650,"text":{"ko":"전열에 선다. 각도 40, 참호 앞은 내가 막는다.","ja":"前列につく。角度四十、塹壕の前はあたしが塞ぐ。"}},{"src":"../assets/voice/sortie/ko/dabin_4.mp3","ms":5370,"text":{"ko":"이송로는 안 닫히게 한다. 마지막 한 명이 빠질 때까지 내가 뛴다.","ja":"移送路は閉じさせない。最後の一人が抜けるまで、あたしが走る。"}},{"src":"../assets/voice/sortie/ko/dabin_5.mp3","ms":4520,"text":{"ko":"사령관, 합류 신호만 줘. 나머진 내가 알아서 돌아 들어간다.","ja":"司令官、合流の合図だけくれ。あとは、あたしが勝手に回り込む。"}}]}};
  const NAMES={"mira":"미라 보스","haneul":"하늘-7","sera":"세라 플린트","astra":"아스트라 벨","tessa":"테사 룬","naru":"나루 세이건","karin":"카린 베가","serin":"세린","luna":"루나","arin":"아린","jaein":"재인 복스","roa":"로아","noella":"노엘라 크로스","ria":"리아","bomin":"보민","orin":"오린 베일","yunseo":"윤서","yura":"유라","yeonhwa":"연화","narae":"나래","moa":"모아","somi":"소미","bella":"벨라 루멘","dana":"다나","mei":"메이","yujin":"유진","iona":"이오나 렉스","harin":"하린","lumi":"루미","yumi":"유미","dabin":"다빈","sion":"시온","liora":"리오라 크레스트","seorin":"서린","eve":"이브 녹턴","chaerin":"채린","soha":"소하","haejin":"해진","yuria":"유리아 글린트","sea":"세아"};
  const DEFAULT_LANG="ja",CAPTION_LANG="ko",POS_KEY="aftersignal:sortie-voice:v1",LANG_KEY="aftersignal:voice-lang",OWNER="sortie";
  const embedded=window.parent!==window;
  const store={get(key){try{return localStorage.getItem(key)}catch{return null}},set(key,value){try{localStorage.setItem(key,value)}catch{}}};
  const muted=()=>store.get("aftersignal:voice-muted")==="1";
  const lang=()=>{const want=store.get(LANG_KEY);return LINES[want]?want:LINES[DEFAULT_LANG]?DEFAULT_LANG:Object.keys(LINES)[0]};
  const linesOf=id=>LINES[lang()]?.[id]||[];
  let pos=(()=>{try{const value=JSON.parse(store.get(POS_KEY)||"{}");return value&&typeof value==="object"?value:{}}catch{return {}}})();
  const positionOf=id=>{const list=linesOf(id),at=Number(pos[lang()]?.[id])||0;return list.length?((at%list.length)+list.length)%list.length:0};

  function next(id){
    const list=linesOf(id);if(!list.length)return null;
    const at=positionOf(id),book=pos[lang()]||(pos[lang()]={});
    book[id]=(at+1)%list.length;store.set(POS_KEY,JSON.stringify(pos));
    return {at,line:list[at]};
  }

  /* ---------- playback ---------- */
  let local=null,playingUntil=0;
  const post=message=>{try{window.parent.postMessage(message,"*")}catch{}};
  const screen=()=>document.body?.dataset.afCommonCombatRuntime?"combat":"lobby";
  function play(line){
    const src=new URL(line.src,document.baseURI).href;
    playingUntil=muted()?0:performance.now()+line.ms;   // VOICE off: nothing plays, nothing to wait for
    try{window.dispatchEvent(new CustomEvent("aftersignal:char-voice",{detail:{owner:OWNER}}))}catch{}
    if(embedded)return post({type:"aftersignal:voice",src,screen:screen()});
    if(muted())return;
    if(local)local.pause();
    local=new Audio(src);local.volume=.92;local.play().catch(()=>{});
  }
  function stop(){
    hideCaption();
    if(performance.now()>=playingUntil)return;
    playingUntil=0;
    if(embedded)post({type:"aftersignal:voice-stop"});else if(local){local.pause();local=null}
  }
  // another voice script took the channel: drop this line without stopping theirs
  window.addEventListener("aftersignal:char-voice",event=>{if(event.detail?.owner!==OWNER){playingUntil=0;hideCaption();if(!embedded&&local){local.pause();local=null}}});

  /* ---------- caption ---------- */
  const style=document.createElement("style");
  style.id="afSortieVoiceStyle";
  style.textContent=`.af-sortievoice-cap{position:fixed;z-index:80;left:50%;top:60%;box-sizing:border-box;width:max-content;max-width:min(460px,calc(100vw - 24px));margin:0;padding:9px 15px 10px;border:1px solid rgba(255,196,110,.5);border-radius:12px;background:linear-gradient(150deg,rgba(34,22,8,.95),rgba(12,8,4,.93));box-shadow:0 12px 32px rgba(0,0,0,.6);color:#fff7ea;font:600 15px/1.5 SignalKR,"Noto Sans KR","Malgun Gothic","Apple SD Gothic Neo","Noto Sans JP","Yu Gothic UI",system-ui,sans-serif;text-align:left;pointer-events:none;opacity:0;transform:translate(-50%,-50%) translateY(6px);transition:opacity .18s ease,transform .18s ease}
.af-sortievoice-cap.show{opacity:1;transform:translate(-50%,-50%)}
.af-sortievoice-cap b{display:block;margin:0 0 2px;color:#ffc975;font:800 11px/1.3 SignalKR,"Noto Sans KR",system-ui,sans-serif;letter-spacing:.08em}
.af-sortievoice-cap b::before{content:"SORTIE // ";color:#ffa84a}
.af-sortievoice-cap.combat{left:auto;right:3%;top:16%;transform:translateY(6px)}
.af-sortievoice-cap.combat.show{transform:none}
@media (max-width:430px){.af-sortievoice-cap{font-size:14px;padding:8px 12px 9px}.af-sortievoice-cap.combat{top:28%;max-width:72%}}
@media (prefers-reduced-motion:reduce){.af-sortievoice-cap{transition:none}}`;
  (document.head||document.documentElement).append(style);
  let cap=null,capTimer=0;
  function hideCaption(){clearTimeout(capTimer);cap?.classList.remove("show")}
  const captionOf=line=>line.text?.[CAPTION_LANG]||line.text?.ko||"";
  function caption(id,line,where){
    if(!cap){cap=document.createElement("div");cap.className="af-sortievoice-cap";cap.setAttribute("role","status");cap.setAttribute("aria-live","polite");cap.append(document.createElement("b"),document.createElement("span"))}
    const host=where.above?.closest?.("dialog[open]")||document.body;
    if(!host)return;
    if(cap.parentNode!==host)host.append(cap);
    cap.firstChild.textContent=NAMES[id]||id;
    cap.lastChild.textContent=captionOf(line);
    cap.lang=CAPTION_LANG;
    cap.classList.remove("show");
    cap.classList.toggle("combat",Boolean(where.combat));
    if(where.combat){cap.style.left="";cap.style.top=""}else place(where);
    void cap.offsetWidth;cap.classList.add("show");
    clearTimeout(capTimer);capTimer=setTimeout(hideCaption,line.ms+900);
  }
  // above the picked formation card when it is on screen, else the middle of the screen
  function place(where){
    const vw=innerWidth,vh=innerHeight,above=where.above?.getBoundingClientRect?.();let x=vw/2,y=vh*.6;
    if(above&&above.width&&above.height){x=above.left+above.width/2;y=above.top-8-cap.offsetHeight/2}
    const w=cap.offsetWidth,h=cap.offsetHeight;
    cap.style.left=Math.round(Math.min(vw-12-w/2,Math.max(12+w/2,x)))+"px";
    cap.style.top=Math.round(Math.min(vh-12-h/2,Math.max(12+h/2,y)))+"px";
  }

  /* ---------- say ---------- */
  function say(id,where={}){
    const pick=next(id);if(!pick)return null;
    play(pick.line);caption(id,pick.line,where);
    return {id,line:pick.at+1,src:pick.line.src,lang:lang()};
  }

  // 출격 편성: the dialog re-renders its cards on click; speak only when this click added the member
  document.addEventListener("click",event=>{
    const pickCard=event.target.closest?.(".gcl-f-card[data-f-pick]");
    if(!pickCard)return;
    const id=pickCard.dataset.fPick,now=[...document.querySelectorAll(".gcl-f-card[data-f-pick]")].find(node=>node.dataset.fPick===id);
    if(pickCard.getAttribute("aria-pressed")!=="true"&&now?.getAttribute("aria-pressed")==="true")say(id,{above:now});
  });

  // battle start: once per page, when the common combat runtime starts the fight
  const leader=()=>String(document.body?.dataset.afDevParty||"").split(",").map(id=>id.trim()).find(id=>linesOf(id).length)||null;
  let deployed=null;
  function onCombatState(){
    const body=document.body;
    if(deployed||!body?.dataset.afCommonCombatRuntime||body.dataset.afCombatStarted!=="true")return;
    const id=leader();if(!id)return;
    deployed=say(id,{combat:true})||{id,line:0};
  }
  function watchCombat(){
    const body=document.body;if(!body?.dataset.afCommonCombatRuntime)return;
    new MutationObserver(onCombatState).observe(body,{attributes:true,attributeFilter:["data-af-combat-started"]});
    onCombatState();
  }
  if(document.body)watchCombat();else document.addEventListener("DOMContentLoaded",watchCombat,{once:true});
  window.addEventListener("pagehide",stop);

  window.AfterSignalSortieVoice=Object.freeze({
    version:"1.1",languages:Object.keys(LINES),lang,captionLang:CAPTION_LANG,
    lines:id=>linesOf(id).map(line=>({...line,text:{...line.text},caption:captionOf(line)})),
    position:id=>positionOf(id)+1,
    say:id=>say(id,{}),
    leader,
    deployed:()=>deployed,
    // ms left of this script's line (0 when idle or another voice took the channel)
    remainingMs:()=>Math.max(0,Math.round(playingUntil-performance.now())),
    stop
  });
})();
